def get_access_token(subject_type, spotify_user_id=None, force_refresh=None, **_extra):
    import json, os, datetime, uuid, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0062000" if __import__("os").path.isdir("./environment_mix/0062000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _utcnow():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(v, str):
            return None
        s = v.strip()
        if not s:
            return None
        if s.endswith("Z"):
            s = s[:-1] + "+00:00"
        try:
            dt = datetime.datetime.fromisoformat(s)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    def _iso(dt):
        if not isinstance(dt, datetime.datetime):
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _log(status, *, oauth_token_id=None, error_message=None, response_status_code=None, response_time_ms=None):
        api_requests = _load("api_requests.json")
        now = _utcnow()
        api_requests.append({
            "id": _new_id("spt_req"),
            "tool_name": "get_access_token",
            "oauth_token_id": oauth_token_id,
            "spotify_endpoint": "/oauth/token",
            "http_method": "POST",
            "request_params": {"subject_type": subject_type, "spotify_user_id": spotify_user_id, "force_refresh": bool(force_refresh) if force_refresh is not None else None},
            "response_status_code": response_status_code,
            "response_time_ms": response_time_ms,
            "result_cache_hit": False,
            "status": status,
            "error_message": error_message,
            "created_at": _iso(now),
            "updated_at": _iso(now),
        })
        _save("api_requests.json", api_requests)

    # Validate inputs
    if subject_type not in ("server", "spotify_user"):
        _log("failed", error_message="subject_type must be one of: server, spotify_user", response_status_code=400, response_time_ms=int((time.time() - t0) * 1000))
        return _err("VALIDATION_ERROR", "subject_type must be one of: server, spotify_user")
    if force_refresh is not None and not isinstance(force_refresh, bool):
        _log("failed", error_message="force_refresh must be a boolean when provided", response_status_code=400, response_time_ms=int((time.time() - t0) * 1000))
        return _err("VALIDATION_ERROR", "force_refresh must be a boolean when provided")
    if subject_type == "spotify_user":
        if not isinstance(spotify_user_id, str) or not spotify_user_id.strip():
            _log("failed", error_message="spotify_user_id is required when subject_type=spotify_user", response_status_code=400, response_time_ms=int((time.time() - t0) * 1000))
            return _err("VALIDATION_ERROR", "spotify_user_id is required when subject_type=spotify_user")
        spotify_user_id = spotify_user_id.strip()
    else:
        # For server token, spotify_user_id must be ignored (accept but do not use)
        spotify_user_id = None

    now = _utcnow()
    oauth_tokens = _load("oauth_tokens.json")

    # Business rule: expire any previously-active server token whose expires_at is in the past
    mutated = False
    if subject_type == "server":
        for r in oauth_tokens:
            if r.get("subject_type") == "server" and r.get("status") == "active":
                exp = _parse_dt(r.get("expires_at"))
                if exp is not None and exp <= now:
                    # transition active -> expired
                    r["status"] = "expired"
                    r["updated_at"] = _iso(now)
                    mutated = True

    # Find matching token row for requested subject (prefer active)
    candidates = []
    for r in oauth_tokens:
        if r.get("subject_type") != subject_type:
            continue
        if subject_type == "spotify_user" and r.get("spotify_user_id") != spotify_user_id:
            continue
        candidates.append(r)

    if not candidates:
        _log("failed", error_message="No stored OAuth token exists for the requested subject", response_status_code=404, response_time_ms=int((time.time() - t0) * 1000))
        return _err("NOT_FOUND", "No stored OAuth token exists for the requested subject", subject_type=subject_type, spotify_user_id=spotify_user_id)

    # Choose active if exists; otherwise most recently updated/created
    active_rows = [r for r in candidates if r.get("status") == "active"]
    if active_rows:
        token_row = sorted(active_rows, key=lambda x: (_parse_dt(x.get("updated_at")) or _parse_dt(x.get("created_at")) or now), reverse=True)[0]
    else:
        token_row = sorted(candidates, key=lambda x: (_parse_dt(x.get("updated_at")) or _parse_dt(x.get("created_at")) or now), reverse=True)[0]

    # Enforce unique active token per subject: if multiple actives exist, keep the newest active and expire others (best-effort repair)
    if token_row.get("status") == "active":
        for r in active_rows:
            if r is token_row:
                continue
            r["status"] = "expired"
            r["updated_at"] = _iso(now)
            mutated = True

    # Determine if refresh is needed
    exp = _parse_dt(token_row.get("expires_at"))
    is_expired = (exp is None) or (exp <= now)
    needs_refresh = bool(force_refresh) or is_expired or token_row.get("status") in ("expired",)

    # If revoked, cannot refresh
    if token_row.get("status") == "revoked":
        if mutated:
            _save("oauth_tokens.json", oauth_tokens)
        _log("failed", oauth_token_id=token_row.get("id"), error_message="Token is revoked and cannot be refreshed", response_status_code=401, response_time_ms=int((time.time() - t0) * 1000))
        return _err("UNAUTHORIZED", "Token is revoked and cannot be refreshed", oauth_token_id=token_row.get("id"))

    # "Refresh" behaviour offline: rotate access_token placeholder and bump expires_at
    # If spotify_user token and no refresh_token, treat refresh as not possible (UNAUTHORIZED) when expired/forced.
    if needs_refresh:
        if subject_type == "spotify_user" and not token_row.get("refresh_token"):
            if mutated:
                _save("oauth_tokens.json", oauth_tokens)
            _log("failed", oauth_token_id=token_row.get("id"), error_message="Token cannot be refreshed (missing refresh_token)", response_status_code=401, response_time_ms=int((time.time() - t0) * 1000))
            return _err("UNAUTHORIZED", "Token cannot be refreshed (missing refresh_token)", oauth_token_id=token_row.get("id"))

        # Transition expired -> active if needed/allowed
        if token_row.get("status") == "expired":
            token_row["status"] = "active"
            mutated = True

        # Ensure token_type
        token_row["token_type"] = "Bearer"

        # Rotate access token to a new opaque value (stored "encrypted at rest" in real service; we store opaque)
        token_row["access_token"] = token_row.get("access_token") or _new_id("spt_acc")
        token_row["access_token"] = f"{token_row['access_token'].split('.')[0]}_{uuid.uuid4().hex}"

        # New expiry (1 hour)
        token_row["expires_at"] = _iso(now + datetime.timedelta(hours=1))
        token_row["updated_at"] = _iso(now)
        mutated = True

    # Update last_used_at always
    token_row["last_used_at"] = _iso(now)
    token_row["updated_at"] = _iso(now)
    mutated = True

    # Constraint: expires_at > created_at
    ca = _parse_dt(token_row.get("created_at")) or now
    ea = _parse_dt(token_row.get("expires_at"))
    if ea is None or ea <= ca:
        # fix forward
        token_row["expires_at"] = _iso(ca + datetime.timedelta(hours=1))
        token_row["updated_at"] = _iso(now)

    if mutated:
        _save("oauth_tokens.json", oauth_tokens)

    _log("succeeded", oauth_token_id=token_row.get("id"), response_status_code=200, response_time_ms=int((time.time() - t0) * 1000))

    # Return a vendor-like envelope
    return {
        "token": {
            "id": token_row.get("id"),
            "token_type": token_row.get("token_type"),
            "access_token": token_row.get("access_token"),
            "scope": token_row.get("scope"),
            "expires_at": token_row.get("expires_at"),
            "subject_type": token_row.get("subject_type"),
            "spotify_user_id": token_row.get("spotify_user_id"),
            "status": token_row.get("status"),
            "last_used_at": token_row.get("last_used_at"),
            "created_at": token_row.get("created_at"),
            "updated_at": token_row.get("updated_at"),
        }
    }

def search(q, type, market=None, limit=None, offset=None, include_external=None, **_extra):
    import json, os, datetime, time, uuid, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0062000" if __import__("os").path.isdir("./environment_mix/0062000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0)

    def _dt_parse(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v
        if not isinstance(v, str) or not v:
            return None
        s = v.strip()
        if s.endswith("Z"):
            s = s[:-1]
        try:
            return datetime.datetime.fromisoformat(s)
        except ValueError:
            return None

    def _dt_dump(dt):
        if isinstance(dt, datetime.datetime):
            return dt.replace(microsecond=0).isoformat() + "Z"
        return dt

    def _gen_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _log_request(tool_name, oauth_token_id, status, error_message=None, spotify_endpoint=None, http_method=None,
                     response_status_code=None, response_time_ms=None, result_cache_hit=False, request_params=None):
        logs = _load("api_requests.json")
        ts = _now()
        row = {
            "id": _gen_id("req"),
            "tool_name": tool_name,
            "oauth_token_id": oauth_token_id,
            "spotify_endpoint": spotify_endpoint,
            "http_method": http_method,
            "request_params": request_params if isinstance(request_params, dict) else (request_params if request_params is None else {"_": request_params}),
            "response_status_code": response_status_code,
            "response_time_ms": response_time_ms,
            "result_cache_hit": bool(result_cache_hit),
            "status": status,
            "error_message": error_message,
            "created_at": _dt_dump(ts),
            "updated_at": _dt_dump(ts),
        }
        logs.append(row)
        _save("api_requests.json", logs)

    t0 = time.time()
    req_params = {
        "q": q, "type": type, "market": market, "limit": limit, "offset": offset, "include_external": include_external
    }

    # Validate
    if not isinstance(q, str) or not q.strip():
        _log_request("search", None, "failed", error_message="q is empty.", request_params=req_params,
                     response_time_ms=int((time.time() - t0) * 1000), result_cache_hit=False)
        return _err("VALIDATION_ERROR", "q must be a non-empty string")
    if not isinstance(type, list) or len(type) < 1:
        _log_request("search", None, "failed", error_message="type missing/empty.", request_params=req_params,
                     response_time_ms=int((time.time() - t0) * 1000), result_cache_hit=False)
        return _err("VALIDATION_ERROR", "type must be a non-empty array")
    allowed_types = {"artist", "album", "track", "playlist", "audiobook", "chapter"}
    for t in type:
        if t not in allowed_types:
            _log_request("search", None, "failed", error_message="Invalid type entry.", request_params=req_params,
                         response_time_ms=int((time.time() - t0) * 1000), result_cache_hit=False)
            return _err("VALIDATION_ERROR", "type contains invalid value(s)")
    if limit is None:
        limit = 20
    if offset is None:
        offset = 0
    if not isinstance(limit, int) or limit < 1 or limit > 50:
        _log_request("search", None, "failed", error_message="Invalid limit.", request_params=req_params,
                     response_time_ms=int((time.time() - t0) * 1000), result_cache_hit=False)
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 50")
    if not isinstance(offset, int) or offset < 0:
        _log_request("search", None, "failed", error_message="Invalid offset.", request_params=req_params,
                     response_time_ms=int((time.time() - t0) * 1000), result_cache_hit=False)
        return _err("VALIDATION_ERROR", "offset must be an integer >= 0")
    if market is not None:
        if not isinstance(market, str) or not re.fullmatch(r"[A-Za-z]{2}", market.strip() or ""):
            _log_request("search", None, "failed", error_message="Invalid market.", request_params=req_params,
                         response_time_ms=int((time.time() - t0) * 1000), result_cache_hit=False)
            return _err("VALIDATION_ERROR", "market must be an ISO 3166-1 alpha-2 country code when provided")
        market = market.upper()
    if include_external is not None and include_external != "audio":
        _log_request("search", None, "failed", error_message="Invalid include_external.", request_params=req_params,
                     response_time_ms=int((time.time() - t0) * 1000), result_cache_hit=False)
        return _err("VALIDATION_ERROR", "include_external must be 'audio' when provided")

    # Require active server token
    tokens = _load("oauth_tokens.json")
    now = _now()
    active_server = None
    for r in tokens:
        if r.get("subject_type") == "server" and r.get("status") == "active":
            exp = _dt_parse(r.get("expires_at"))
            if exp and exp > now:
                active_server = r
                break
    if not active_server:
        _log_request("search", None, "failed", error_message="No valid server token.", request_params=req_params,
                     spotify_endpoint="/v1/search", http_method="GET",
                     response_status_code=401, response_time_ms=int((time.time() - t0) * 1000),
                     result_cache_hit=False)
        return _err("UNAUTHORIZED", "No valid server access token is available")

    # Update last_used_at
    active_server["last_used_at"] = _dt_dump(now)
    active_server["updated_at"] = _dt_dump(now)
    _save("oauth_tokens.json", tokens)

    # Offline behavior: serve search from local catalog cache only.
    items = _load("catalog_items.json")

    q_norm = q.strip().lower()

    def _matches(item):
        if item.get("cache_status") == "evicted":
            return False
        name = (item.get("name") or "").lower()
        desc = (item.get("description_text") or "").lower()
        # simple contains match
        return q_norm in name or (q_norm in desc if desc else False)

    def _paging_for(entity_type):
        filtered = [it for it in items if it.get("entity_type") == entity_type and _matches(it)]
        total = len(filtered)
        # deterministic order: popularity desc, then name asc, then spotify_id
        def _key(it):
            pop = it.get("popularity")
            popv = pop if isinstance(pop, int) else -1
            return (-popv, (it.get("name") or "").lower(), it.get("spotify_id") or "")
        filtered.sort(key=_key)
        page = filtered[offset: offset + limit]
        # Spotify-style paging object
        return {
            "href": None,
            "items": [it.get("raw_json") for it in page if isinstance(it.get("raw_json"), dict)],
            "limit": limit,
            "next": None if offset + limit >= total else None,
            "offset": offset,
            "previous": None if offset == 0 else None,
            "total": total,
        }

    response = {}
    for t in type:
        plural = t + "s" if t != "audiobook" else "audiobooks"
        if t == "category":  # not allowed in search tool
            continue
        response[plural] = _paging_for(t)

    # Log: outbound call attempted in real API; here we indicate "no cache hit" (search is not a catalog cache read rule)
    _log_request("search", active_server.get("id"), "succeeded",
                 request_params=req_params,
                 spotify_endpoint="/v1/search", http_method="GET",
                 response_status_code=200, response_time_ms=int((time.time() - t0) * 1000),
                 result_cache_hit=False)

    return response

def get_artist(artist_id, **_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0062000" if __import__("os").path.isdir("./environment_mix/0062000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    started = datetime.datetime.now(datetime.timezone.utc)

    def _utcnow():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(v, str):
            return None
        s = v.strip()
        if not s:
            return None
        if s.endswith("Z"):
            s = s[:-1] + "+00:00"
        try:
            dt = datetime.datetime.fromisoformat(s)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except ValueError:
            return None

    def _iso(dt):
        if not isinstance(dt, datetime.datetime):
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _ms():
        return max(0, int((_utcnow() - started).total_seconds() * 1000))

    def _new_id(prefix):
        import uuid
        return f"{prefix}_{uuid.uuid4().hex}"

    def _log(status, oauth_token_id=None, result_cache_hit=False, spotify_endpoint=None, http_method=None,
             response_status_code=None, response_time_ms=None, error_message=None, request_params=None):
        now = _utcnow()
        api_requests = _load("api_requests.json")
        api_requests.append({
            "id": _new_id("spt_req"),
            "tool_name": "get_artist",
            "oauth_token_id": oauth_token_id,
            "spotify_endpoint": spotify_endpoint,
            "http_method": http_method,
            "request_params": request_params if isinstance(request_params, dict) else {"artist_id": artist_id},
            "response_status_code": response_status_code,
            "response_time_ms": response_time_ms,
            "result_cache_hit": bool(result_cache_hit),
            "status": status,
            "error_message": error_message,
            "created_at": _iso(now),
            "updated_at": _iso(now),
        })
        _save("api_requests.json", api_requests)

    # Validate
    if not isinstance(artist_id, str) or not artist_id.strip():
        _log("failed", error_message="artist_id is required", request_params={"artist_id": artist_id})
        return _err("VALIDATION_ERROR", "artist_id is required", artist_id=artist_id)
    artist_id = artist_id.strip()

    # Auth: server token required for public catalog endpoints
    oauth_tokens = _load("oauth_tokens.json")
    now = _utcnow()
    changed = False
    for tok in oauth_tokens:
        if tok.get("subject_type") == "server" and tok.get("status") == "active":
            exp = _parse_dt(tok.get("expires_at"))
            if exp is not None and exp <= now:
                tok["status"] = "expired"
                tok["updated_at"] = _iso(now)
                changed = True
    if changed:
        _save("oauth_tokens.json", oauth_tokens)

    token = None
    for tok in oauth_tokens:
        if tok.get("subject_type") == "server" and tok.get("status") == "active":
            exp = _parse_dt(tok.get("expires_at"))
            if exp is None or exp > now:
                token = tok
                break
    if token is None:
        _log("failed", oauth_token_id=None, error_message="No active OAuth token available for server subject",
             request_params={"artist_id": artist_id})
        return _err("UNAUTHORIZED", "No active OAuth token available for server subject")

    # Cache lookup
    catalog_items = _load("catalog_items.json")
    fresh = None
    for it in catalog_items:
        if it.get("entity_type") == "artist" and it.get("spotify_id") == artist_id:
            if it.get("cache_status") == "fresh":
                exp = _parse_dt(it.get("expires_at"))
                if exp is not None and exp > now:
                    fresh = it
                    break
    if fresh is not None:
        token["last_used_at"] = _iso(now)
        token["updated_at"] = _iso(now)
        _save("oauth_tokens.json", oauth_tokens)
        _log("succeeded", oauth_token_id=token.get("id"), result_cache_hit=True,
             spotify_endpoint="/v1/artists/{id}", http_method="GET",
             response_status_code=200, response_time_ms=_ms(),
             request_params={"artist_id": artist_id})
        return {"artist": fresh.get("raw_json")}

    # Offline backend: if not cached, treat as not found (no upstream available)
    token["last_used_at"] = _iso(now)
    token["updated_at"] = _iso(now)
    _save("oauth_tokens.json", oauth_tokens)
    _log("failed", oauth_token_id=token.get("id"), result_cache_hit=False,
         spotify_endpoint="/v1/artists/{id}", http_method="GET",
         response_status_code=404, response_time_ms=_ms(),
         error_message="Artist not found in local cache (offline mode)",
         request_params={"artist_id": artist_id})
    return _err("NOT_FOUND", "Artist not found", artist_id=artist_id)

