    def _log_request(tool_name, oauth_token_id, status, error_message=None, spotify_endpoint=None, http_method=None,
                     response_status_code=None, response_time_ms=None, result_cache_hit=False, request_params=None):
        logs = _load("api_requests.json")
        ts = _now()
        row = {
            "id": _gen_id("req"),
            "tool_name": tool_name,
            "oauth_token_id": oauth_token_id,
            "spotify_endpoint": spotify_endpoint,
            "http_method": http_method,
            "request_params": request_params if isinstance(request_params, dict) else (request_params if request_params is None else {"_": request_params}),
            "response_status_code": response_status_code,
            "response_time_ms": response_time_ms,
            "result_cache_hit": bool(result_cache_hit),
            "status": status,
            "error_message": error_message,
            "created_at": _dt_dump(ts),
            "updated_at": _dt_dump(ts),
        }
        logs.append(row)
        _save("api_requests.json", logs)

    t0 = time.time()
    req_params = {"artist_ids": artist_ids}

    # Validate
    if not isinstance(artist_ids, list) or len(artist_ids) < 1:
        _log_request("get_multiple_artists", None, "failed", error_message="artist_ids empty.", request_params=req_params,
                     response_time_ms=int((time.time() - t0) * 1000), result_cache_hit=False)
        return _err("VALIDATION_ERROR", "artist_ids must be a non-empty array")
    if len(artist_ids) > 50:
        _log_request("get_multiple_artists", None, "failed", error_message="artist_ids too many.", request_params=req_params,
                     response_time_ms=int((time.time() - t0) * 1000), result_cache_hit=False)
        return _err("VALIDATION_ERROR", "artist_ids must contain no more than 50 IDs")
    norm_ids = []
    for a in artist_ids:
        if not isinstance(a, str) or not a.strip():
            _log_request("get_multiple_artists", None, "failed", error_message="Invalid artist id in list.", request_params=req_params,
                         response_time_ms=int((time.time() - t0) * 1000), result_cache_hit=False)
            return _err("VALIDATION_ERROR", "artist_ids must contain only non-empty strings")
        norm_ids.append(a.strip())

    # Require active server token
    tokens = _load("oauth_tokens.json")
    now = _now()
    active_server = None
    for r in tokens:
        if r.get("subject_type") == "server" and r.get("status") == "active":
            exp = _dt_parse(r.get("expires_at"))
            if exp and exp > now:
                active_server = r
                break
    if not active_server:
        _log_request("get_multiple_artists", None, "failed", error_message="No valid server token.", request_params=req_params,
                     spotify_endpoint="/v1/artists?ids=...", http_method="GET",
                     response_status_code=401, response_time_ms=int((time.time() - t0) * 1000),
                     result_cache_hit=False)
        return _err("UNAUTHORIZED", "No valid access token is available")

    items = _load("catalog_items.json")

    # Build a lookup for fresh cached artists
    fresh = {}
    for it in items:
        if it.get("entity_type") != "artist":
            continue
        if it.get("cache_status") != "fresh":
            continue
        exp = _dt_parse(it.get("expires_at"))
        if not exp or exp <= now:
            continue
        sid = it.get("spotify_id")
        if sid and isinstance(it.get("raw_json"), dict):
            fresh[sid] = it["raw_json"]

    # Result in requested order; if any missing, offline cannot fetch -> None entries like Spotify does for unknown ids,
    # but tool description says NOT_FOUND for single and doesn't specify for multiple; Spotify returns nulls.
    # We'll return None for those that are not available.
    artists = [fresh.get(a) for a in norm_ids]

    # Update token last_used_at
    active_server["last_used_at"] = _dt_dump(now)
    active_server["updated_at"] = _dt_dump(now)
    _save("oauth_tokens.json", tokens)

    # Consider cache hit if all requested were served from cache; otherwise false.
    all_hit = all(x is not None for x in artists)

    _log_request("get_multiple_artists", active_server.get("id"), "succeeded",
                 request_params=req_params,
                 spotify_endpoint=None if all_hit else "/v1/artists",
                 http_method=None if all_hit else "GET",
                 response_status_code=None if all_hit else 200,
                 response_time_ms=int((time.time() - t0) * 1000),
                 result_cache_hit=bool(all_hit))

    return {"artists": artists}

