def get_multiple_albums(album_spotify_ids, market=None, **_extra):
    import json, os, datetime, time, re, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0062000" if __import__("os").path.isdir("./environment_mix/0062000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    start = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now.isoformat() + "Z"

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, (int, float)):
            return datetime.datetime.utcfromtimestamp(s).replace(microsecond=0)
        if not isinstance(s, str):
            return None
        t = s.strip()
        if t.endswith("Z"):
            t = t[:-1]
        try:
            return datetime.datetime.fromisoformat(t).replace(microsecond=0)
        except Exception:
            return None

    def _is_iso2(m):
        return isinstance(m, str) and re.fullmatch(r"[A-Z]{2}", m.strip().upper() or "") is not None

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _log(status, *, oauth_token_id=None, spotify_endpoint=None, http_method=None,
             response_status_code=None, response_time_ms=None, result_cache_hit=False, error_message=None,
             request_params=None):
        api_requests = _load("api_requests.json")
        row = {
            "id": _new_id("req"),
            "tool_name": "get_multiple_albums",
            "oauth_token_id": oauth_token_id,
            "spotify_endpoint": spotify_endpoint,
            "http_method": http_method,
            "request_params": request_params,
            "response_status_code": response_status_code,
            "response_time_ms": response_time_ms,
            "result_cache_hit": bool(result_cache_hit),
            "status": status,
            "error_message": error_message,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        api_requests.append(row)
        _save("api_requests.json", api_requests)

    def _rate_limit_check():
        api_requests = _load("api_requests.json")
        one_min_ago = now - datetime.timedelta(seconds=60)
        one_day_ago = now - datetime.timedelta(days=1)
        c_min = 0
        c_day = 0
        for r in api_requests:
            dt = _parse_dt(r.get("created_at"))
            if not dt:
                continue
            if dt >= one_min_ago:
                c_min += 1
            if dt >= one_day_ago:
                c_day += 1
        if c_min >= 120:
            return _err("RATE_LIMIT", "Too many requests in a short period; please retry later.")
        if c_day >= 5000:
            return _err("QUOTA_EXCEEDED", "Daily request quota exceeded; please retry later.")
        return None

    def _resolve_active_server_token():
        tokens = _load("oauth_tokens.json")
        changed = False
        for t in tokens:
            if t.get("subject_type") == "server" and t.get("status") == "active":
                exp = _parse_dt(t.get("expires_at"))
                if exp and exp <= now:
                    t["status"] = "expired"
                    t["updated_at"] = now_iso
                    changed = True
        if changed:
            _save("oauth_tokens.json", tokens)
        best = None
        best_exp = None
        for t in tokens:
            if t.get("subject_type") != "server" or t.get("status") != "active":
                continue
            exp = _parse_dt(t.get("expires_at"))
            if not exp or exp <= now:
                continue
            if best is None or exp > best_exp:
                best = t
                best_exp = exp
        return best

    # --- validate ---
    if not isinstance(album_spotify_ids, list) or len(album_spotify_ids) < 1 or len(album_spotify_ids) > 20:
        e = _err("VALIDATION_ERROR", "album_spotify_ids must be an array with 1 to 20 Spotify IDs.")
        rl = _rate_limit_check()
        if rl:
            _log("failed", error_message=rl["error"]["message"], request_params={"album_spotify_ids": album_spotify_ids, "market": market})
            return rl
        _log("failed", error_message=e["error"]["message"], request_params={"album_spotify_ids": album_spotify_ids, "market": market})
        return e
    cleaned = []
    for x in album_spotify_ids:
        if not isinstance(x, str) or not x.strip():
            e = _err("VALIDATION_ERROR", "album_spotify_ids must contain only non-empty strings.")
            rl = _rate_limit_check()
            if rl:
                _log("failed", error_message=rl["error"]["message"], request_params={"album_spotify_ids": album_spotify_ids, "market": market})
                return rl
            _log("failed", error_message=e["error"]["message"], request_params={"album_spotify_ids": album_spotify_ids, "market": market})
            return e
        cleaned.append(x.strip())
    album_spotify_ids = cleaned

    if market is not None:
        if not isinstance(market, str) or not _is_iso2(market):
            e = _err("VALIDATION_ERROR", "market must be a valid ISO 3166-1 alpha-2 country code.")
            rl = _rate_limit_check()
            if rl:
                _log("failed", error_message=rl["error"]["message"], request_params={"album_spotify_ids": album_spotify_ids, "market": market})
                return rl
            _log("failed", error_message=e["error"]["message"], request_params={"album_spotify_ids": album_spotify_ids, "market": market})
            return e
        market = market.strip().upper()

    rl = _rate_limit_check()
    if rl:
        _log("failed", error_message=rl["error"]["message"], request_params={"album_spotify_ids": album_spotify_ids, "market": market})
        return rl

    tok = _resolve_active_server_token()
    if not tok:
        _log("failed", oauth_token_id=None, error_message="No active server OAuth token available.", request_params={"album_spotify_ids": album_spotify_ids, "market": market})
        return _err("UNAUTHORIZED", "No active server OAuth token available.")

    # mark last_used_at
    tokens = _load("oauth_tokens.json")
    for t in tokens:
        if t.get("id") == tok.get("id"):
            t["last_used_at"] = now_iso
            t["updated_at"] = now_iso
            break
    _save("oauth_tokens.json", tokens)

    items = _load("catalog_items.json")
    by_key = {}
    for it in items:
        if it.get("entity_type") == "album" and isinstance(it.get("spotify_id"), str):
            by_key[it["spotify_id"]] = it

    albums = []
    all_found = True
    for sid in album_spotify_ids:
        it = by_key.get(sid)
        if not it:
            all_found = False
            albums.append(None)
            continue
        raw = it.get("raw_json")
        if isinstance(raw, dict):
            albums.append(raw)
        else:
            albums.append({"id": it.get("spotify_id"), "type": "album", "name": it.get("name")})

    _log("succeeded",
         oauth_token_id=tok.get("id"),
         spotify_endpoint="/v1/albums",
         http_method="GET",
         response_status_code=200,
         response_time_ms=max(0, int((time.time() - start) * 1000)),
         result_cache_hit=True,
         request_params={"album_spotify_ids": album_spotify_ids, "market": market})

    return {
        "albums": albums,
        "requested_ids": album_spotify_ids,
        "all_found": all_found
    }

