            return datetime.datetime.utcfromtimestamp(s).replace(microsecond=0)
        if not isinstance(s, str):
            return None
        t = s.strip()
        if t.endswith("Z"):
            t = t[:-1]
        try:
            return datetime.datetime.fromisoformat(t).replace(microsecond=0)
        except Exception:
            return None

    def _is_iso2(m):
        return isinstance(m, str) and re.fullmatch(r"[A-Z]{2}", m.strip().upper() or "") is not None

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _log(status, *, oauth_token_id=None, spotify_endpoint=None, http_method=None,
             response_status_code=None, response_time_ms=None, result_cache_hit=False, error_message=None,
             request_params=None):
        api_requests = _load("api_requests.json")
        row = {
            "id": _new_id("req"),
            "tool_name": "get_track",
            "oauth_token_id": oauth_token_id,
            "spotify_endpoint": spotify_endpoint,
            "http_method": http_method,
            "request_params": request_params,
            "response_status_code": response_status_code,
            "response_time_ms": response_time_ms,
            "result_cache_hit": bool(result_cache_hit),
            "status": status,
            "error_message": error_message,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        api_requests.append(row)
        _save("api_requests.json", api_requests)

    def _rate_limit_check():
        api_requests = _load("api_requests.json")
        one_min_ago = now - datetime.timedelta(seconds=60)
        one_day_ago = now - datetime.timedelta(days=1)
        c_min = 0
        c_day = 0
        for r in api_requests:
            dt = _parse_dt(r.get("created_at"))
            if not dt:
                continue
            if dt >= one_min_ago:
                c_min += 1
            if dt >= one_day_ago:
                c_day += 1
        if c_min >= 120:
            return _err("RATE_LIMIT", "Too many requests in a short period; please retry later.")
        if c_day >= 5000:
            return _err("QUOTA_EXCEEDED", "Daily request quota exceeded; please retry later.")
        return None

    def _resolve_active_server_token():
        tokens = _load("oauth_tokens.json")
        changed = False
        for t in tokens:
            if t.get("subject_type") == "server" and t.get("status") == "active":
                exp = _parse_dt(t.get("expires_at"))
                if exp and exp <= now:
                    t["status"] = "expired"
                    t["updated_at"] = now_iso
                    changed = True
        if changed:
            _save("oauth_tokens.json", tokens)
        best = None
        best_exp = None
        for t in tokens:
            if t.get("subject_type") != "server" or t.get("status") != "active":
                continue
            exp = _parse_dt(t.get("expires_at"))
            if not exp or exp <= now:
                continue
            if best is None or exp > best_exp:
                best = t
                best_exp = exp
        return best

    def _find_track_item():
        items = _load("catalog_items.json")
        for it in items:
            if it.get("entity_type") == "track" and it.get("spotify_id") == track_spotify_id:
                return it
        return None

    # --- validate ---
    if not isinstance(track_spotify_id, str) or not track_spotify_id.strip():
        e = _err("VALIDATION_ERROR", "track_spotify_id must be a non-empty string.")
        rl = _rate_limit_check()
        if rl:
            _log("failed", error_message=rl["error"]["message"], request_params={"track_spotify_id": track_spotify_id, "market": market})
            return rl
        _log("failed", error_message=e["error"]["message"], request_params={"track_spotify_id": track_spotify_id, "market": market})
        return e
    track_spotify_id = track_spotify_id.strip()

    if market is not None:
        if not isinstance(market, str) or not _is_iso2(market):
            e = _err("VALIDATION_ERROR", "market must be a valid ISO 3166-1 alpha-2 country code.")
            rl = _rate_limit_check()
            if rl:
                _log("failed", error_message=rl["error"]["message"], request_params={"track_spotify_id": track_spotify_id, "market": market})
                return rl
            _log("failed", error_message=e["error"]["message"], request_params={"track_spotify_id": track_spotify_id, "market": market})
            return e
        market = market.strip().upper()

    rl = _rate_limit_check()
    if rl:
        _log("failed", error_message=rl["error"]["message"], request_params={"track_spotify_id": track_spotify_id, "market": market})
        return rl

    tok = _resolve_active_server_token()
    if not tok:
        _log("failed", oauth_token_id=None, error_message="No active server OAuth token available.", request_params={"track_spotify_id": track_spotify_id, "market": market})
        return _err("UNAUTHORIZED", "No active server OAuth token available.")

    # mark last_used_at
    tokens = _load("oauth_tokens.json")
    for t in tokens:
        if t.get("id") == tok.get("id"):
            t["last_used_at"] = now_iso
            t["updated_at"] = now_iso
            break
    _save("oauth_tokens.json", tokens)

    it = _find_track_item()
    if not it:
        _log("failed",
             oauth_token_id=tok.get("id"),
             spotify_endpoint=f"/v1/tracks/{track_spotify_id}",
             http_method="GET",
             response_status_code=404,
             response_time_ms=max(0, int((time.time() - start) * 1000)),
             result_cache_hit=True,
             error_message="Track not found in cache.",
             request_params={"track_spotify_id": track_spotify_id, "market": market})
        return _err("NOT_FOUND", "Track not found.")

    raw = it.get("raw_json")
    if not isinstance(raw, dict):
        raw = {"id": it.get("spotify_id"), "type": "track", "name": it.get("name")}

    _log("succeeded",
         oauth_token_id=tok.get("id"),
         spotify_endpoint=f"/v1/tracks/{track_spotify_id}",
         http_method="GET",
         response_status_code=200,
         response_time_ms=max(0, int((time.time() - start) * 1000)),
         result_cache_hit=True,
         request_params={"track_spotify_id": track_spotify_id, "market": market})

    return raw

def get_available_genres(**_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0062000" if __import__("os").path.isdir("./environment_mix/0062000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _utcnow():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(v, str):
            return None
        s = v.strip()
        if not s:
            return None
        if s.endswith("Z"):
            s = s[:-1] + "+00:00"
        try:
            dt = datetime.datetime.fromisoformat(s)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    def _iso(dt):
        if not isinstance(dt, datetime.datetime):
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _log(status, *, oauth_token_id=None, error_message=None, response_status_code=None, response_time_ms=None):
        api_requests = _load("api_requests.json")
        now = _utcnow()
        api_requests.append({
            "id": _new_id("spt_req"),
            "tool_name": "get_available_genres",
            "oauth_token_id": oauth_token_id,
            "spotify_endpoint": "/v1/recommendations/available-genre-seeds",
            "http_method": "GET",
            "request_params": {},
            "response_status_code": response_status_code,
            "response_time_ms": response_time_ms,
            "result_cache_hit": False,
            "status": status,
            "error_message": error_message,
            "created_at": _iso(now),
            "updated_at": _iso(now),
        })
        _save("api_requests.json", api_requests)

    now = _utcnow()

    # Require active server token (no cache table for genres in schema; just authenticate/log)
    oauth_tokens = _load("oauth_tokens.json")
    usable = []
    for t in oauth_tokens:
        if t.get("subject_type") == "server" and t.get("status") == "active":
            exp = _parse_dt(t.get("expires_at"))
            if exp is not None and exp > now:
                usable.append(t)
    if not usable:
        _log("failed", error_message="No active server OAuth token available", response_status_code=401, response_time_ms=int((time.time() - t0) * 1000))
        return _err("UNAUTHORIZED", "No active server OAuth token available")
    token_row = sorted(usable, key=lambda x: _parse_dt(x.get("updated_at")) or _parse_dt(x.get("created_at")) or now, reverse=True)[0]

    # Offline dataset: derive from existing recommendation_requests seed_genres + common Spotify genres as fallback
    recs = _load("recommendation_requests.json")
    genres = set()
    for r in recs:
        sg = r.get("seed_genres")
        if isinstance(sg, list):
            for g in sg:
                if isinstance(g, str) and g.strip():
                    genres.add(g.strip().lower())
    # ensure non-empty stable output
    fallback = ["pop", "rock", "hip-hop", "indie", "dance", "electronic", "r-n-b", "jazz", "metal", "classical"]
    if not genres:
        genres.update(fallback)
    out = sorted(genres)

    token_row["last_used_at"] = _iso(now)
    token_row["updated_at"] = _iso(now)
    _save("oauth_tokens.json", oauth_tokens)

    _log("succeeded", oauth_token_id=token_row.get("id"), response_status_code=200, response_time_ms=int((time.time() - t0) * 1000))
    return {"genres": out}

def get_new_releases(country=None, limit=None, offset=None, **_extra):
    import json, os, datetime, time, random, string

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0062000" if __import__("os").path.isdir("./environment_mix/0062000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.isoformat()
        return dt

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _new_id(prefix):
        ts = int(time.time() * 1000)
        rnd = "".join(random.choice(string.ascii_lowercase + string.digits) for _ in range(8))
        return f"{prefix}_{ts}_{rnd}"

    def _is_iso2(x):
        return isinstance(x, str) and len(x) == 2 and x.isalpha() and x.upper() == x

    # ---- validate inputs ----
    if country is not None and not _is_iso2(country):
        # accept lowercase by normalizing? spec says raise if not valid; we can normalize only if alpha2.
        if isinstance(country, str) and len(country) == 2 and country.isalpha():
            country = country.upper()
        else:
            return _err("VALIDATION_ERROR", "country must be an ISO 3166-1 alpha-2 code (e.g., 'US').")
    if limit is not None:
        if not isinstance(limit, int):
            return _err("VALIDATION_ERROR", "limit must be an integer.")
        if limit < 1 or limit > 50:
            return _err("VALIDATION_ERROR", "limit must be between 1 and 50.")
    if offset is not None:
        if not isinstance(offset, int):
            return _err("VALIDATION_ERROR", "offset must be an integer.")
        if offset < 0:
            return _err("VALIDATION_ERROR", "offset must be >= 0.")

    limit = 20 if limit is None else limit
    offset = 0 if offset is None else offset

    t0 = time.time()
    api_requests = _load("api_requests.json")
    oauth_tokens = _load("oauth_tokens.json")
    catalog_items = _load("catalog_items.json")
    catalog_links = _load("catalog_links.json")

    now = _now()

    # ---- quota / rate limit (based on audited outbound Spotify calls) ----
    # Simple server-side policy (offline datastore): 60 Spotify calls/minute and 1000 Spotify calls/day
    # counted via api_requests with spotify_endpoint present.
    one_min_ago = now - datetime.timedelta(seconds=60)
    day_ago = now - datetime.timedelta(days=1)

    calls_last_min = 0
    calls_last_day = 0
    for r in api_requests:
        ep = r.get("spotify_endpoint")
        if not ep:
            continue
        created = _parse_dt(r.get("created_at"))
        if not created:
            continue
        if created >= one_min_ago:
            calls_last_min += 1
        if created >= day_ago:
            calls_last_day += 1

    if calls_last_min >= 60:
        # log refusal
        rid = _new_id("req")
        row = {
            "id": rid,
            "tool_name": "get_new_releases",
            "oauth_token_id": None,
            "spotify_endpoint": "/v1/browse/new-releases",
            "http_method": "GET",
            "request_params": {"country": country, "limit": limit, "offset": offset},
            "response_status_code": None,
            "response_time_ms": int((time.time() - t0) * 1000),
            "result_cache_hit": False,
            "status": "failed",
            "error_message": "Rate limit exceeded (60 calls/min).",
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        api_requests.append(row)
        _save("api_requests.json", api_requests)
        return _err("RATE_LIMIT", "Too many requests. Please slow down.")
    if calls_last_day >= 1000:
        rid = _new_id("req")
        row = {
            "id": rid,
            "tool_name": "get_new_releases",
            "oauth_token_id": None,
            "spotify_endpoint": "/v1/browse/new-releases",
            "http_method": "GET",
            "request_params": {"country": country, "limit": limit, "offset": offset},
            "response_status_code": None,
            "response_time_ms": int((time.time() - t0) * 1000),
            "result_cache_hit": False,
            "status": "failed",
            "error_message": "Daily quota exceeded (1000 calls/day).",
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        api_requests.append(row)
        _save("api_requests.json", api_requests)
        return _err("QUOTA_EXCEEDED", "Daily quota exceeded.")

    # ---- resolve a usable server token ----
    # expire past-due active server tokens
    for tok in oauth_tokens:
        if tok.get("subject_type") == "server" and tok.get("status") == "active":
            exp = _parse_dt(tok.get("expires_at"))
            if exp and exp <= now:
                # transition active->expired
                tok["status"] = "expired"
                tok["updated_at"] = _iso(now)

    active_server = None
    for tok in oauth_tokens:
        if tok.get("subject_type") == "server" and tok.get("status") == "active":
            exp = _parse_dt(tok.get("expires_at"))
            if exp and exp > now:
                active_server = tok
                break

    if not active_server:
        # log failure
        rid = _new_id("req")
        row = {
            "id": rid,
            "tool_name": "get_new_releases",
            "oauth_token_id": None,
            "spotify_endpoint": "/v1/browse/new-releases",
            "http_method": "GET",
            "request_params": {"country": country, "limit": limit, "offset": offset},
            "response_status_code": None,
            "response_time_ms": int((time.time() - t0) * 1000),
            "result_cache_hit": False,
            "status": "failed",
            "error_message": "No active server OAuth token available.",
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        api_requests.append(row)
        _save("api_requests.json", api_requests)
        _save("oauth_tokens.json", oauth_tokens)
        return _err("UNAUTHORIZED", "No valid Spotify OAuth token available for server requests.")

    # ---- ensure synthetic category item for new releases ----
    syn = None
    for ci in catalog_items:
        if ci.get("entity_type") == "category" and ci.get("spotify_id") == "new_releases":
            syn = ci
            break
    if syn is None:
        cid = _new_id("cat")
        syn = {
            "id": cid,
            "spotify_id": "new_releases",
            "entity_type": "category",
            "uri": "spotify:category:new_releases",
            "href": None,
            "name": "New Releases",
            "description_text": None,
            "is_public": None,
            "owner_spotify_user_id": None,
            "release_date": None,
            "duration_ms": None,
            "popularity": None,
            "explicit": None,
            "languages": None,
            "genres": None,
            "images": None,
            "external_urls": None,
            "raw_json": {"id": "new_releases", "name": "New Releases", "type": "category"},
            "cache_status": "fresh",
            "cached_at": _iso(now),
            "expires_at": _iso(now + datetime.timedelta(days=3650)),
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        catalog_items.append(syn)

    # ---- "call Spotify": offline implementation uses cached catalog_links/items ----
    # We treat existing link rows as the best available representation; no fabrication.
    # Filter active links from synthetic category.
    active_links = []
    for ln in catalog_links:
        if ln.get("status") != "active":
            continue
        if ln.get("link_type") != "new_release_album":
            continue
        if ln.get("from_catalog_item_id") != syn.get("id"):
            continue
        # if country is provided, store/restrict via market field (Spotify uses country)
        if country is not None and ln.get("market") not in (None, country):
            continue
        active_links.append(ln)

    # sort by position then created_at as fallback
    def _sort_key(ln):
        pos = ln.get("position")
        if isinstance(pos, int):
            return (0, pos)
        return (1, 0)

    active_links.sort(key=_sort_key)

    total = len(active_links)
    page_links = active_links[offset: offset + limit]
    id_to_item = {ci.get("id"): ci for ci in catalog_items if isinstance(ci.get("id"), str)}
    albums = []
    for ln in page_links:
        ci = id_to_item.get(ln.get("to_catalog_item_id"))
        if not ci:
            continue
        if ci.get("entity_type") != "album":
            continue
        albums.append(ci.get("raw_json"))

    # Log request as succeeded; this tool is a Spotify browse endpoint (assume outbound call)
    active_server["last_used_at"] = _iso(now)
    active_server["updated_at"] = _iso(now)

    rid = _new_id("req")
    row = {
        "id": rid,
        "tool_name": "get_new_releases",
        "oauth_token_id": active_server.get("id"),
        "spotify_endpoint": "/v1/browse/new-releases",
        "http_method": "GET",
        "request_params": {"country": country, "limit": limit, "offset": offset},
        "response_status_code": 200,
        "response_time_ms": int((time.time() - t0) * 1000),
        "result_cache_hit": False,
        "status": "succeeded",
        "error_message": None,
        "created_at": _iso(now),
        "updated_at": _iso(now),
    }
    api_requests.append(row)

    _save("oauth_tokens.json", oauth_tokens)
    _save("catalog_items.json", catalog_items)
    _save("catalog_links.json", catalog_links)
    _save("api_requests.json", api_requests)

    return {
        "albums": {
            "href": None,
            "items": albums,
            "limit": limit,
            "next": None,
            "offset": offset,
            "previous": None,
            "total": total,
        }
    }

