                return None
        return out

    tracks = _clean_list(seed_tracks_spotify_ids)
    artists = _clean_list(seed_artists_spotify_ids)
    genres = _clean_list(seed_genres)
    if tracks is None or artists is None or genres is None:
        return _err("VALIDATION_ERROR", "Seed lists must contain only non-empty strings.")

    if len(tracks) + len(artists) + len(genres) == 0:
        return _err("VALIDATION_ERROR", "At least one seed must be provided (tracks, artists, or genres).")
    if len(tracks) + len(artists) + len(genres) > 5:
        return _err("VALIDATION_ERROR", "No more than 5 total seed values are allowed across tracks+artists+genres.")

    t0 = time.time()
    now = _now()

    api_requests = _load("api_requests.json")
    oauth_tokens = _load("oauth_tokens.json")
    catalog_items = _load("catalog_items.json")
    recommendation_requests = _load("recommendation_requests.json")

    # ---- rate limit / quota (outbound calls) ----
    one_min_ago = now - datetime.timedelta(seconds=60)
    day_ago = now - datetime.timedelta(days=1)
    calls_last_min = 0
    calls_last_day = 0
    for r in api_requests:
        if not r.get("spotify_endpoint"):
            continue
        created = _parse_dt(r.get("created_at"))
        if not created:
            continue
        if created >= one_min_ago:
            calls_last_min += 1
        if created >= day_ago:
            calls_last_day += 1
    if calls_last_min >= 60:
        rid = _new_id("req")
        api_requests.append({
            "id": rid,
            "tool_name": "get_recommendations",
            "oauth_token_id": None,
            "spotify_endpoint": "/v1/recommendations",
            "http_method": "GET",
            "request_params": {
                "seed_tracks_spotify_ids": tracks,
                "seed_artists_spotify_ids": artists,
                "seed_genres": genres,
                "market": market,
                "limit": limit,
                "tunable_attributes": tunable_attributes,
            },
            "response_status_code": None,
            "response_time_ms": int((time.time() - t0) * 1000),
            "result_cache_hit": False,
            "status": "failed",
            "error_message": "Rate limit exceeded (60 calls/min).",
            "created_at": _iso(now),
            "updated_at": _iso(now),
        })
        _save("api_requests.json", api_requests)
        return _err("RATE_LIMIT", "Too many requests. Please slow down.")
    if calls_last_day >= 1000:
        rid = _new_id("req")
        api_requests.append({
            "id": rid,
            "tool_name": "get_recommendations",
            "oauth_token_id": None,
            "spotify_endpoint": "/v1/recommendations",
            "http_method": "GET",
            "request_params": {
                "seed_tracks_spotify_ids": tracks,
                "seed_artists_spotify_ids": artists,
                "seed_genres": genres,
                "market": market,
                "limit": limit,
                "tunable_attributes": tunable_attributes,
            },
            "response_status_code": None,
            "response_time_ms": int((time.time() - t0) * 1000),
            "result_cache_hit": False,
            "status": "failed",
            "error_message": "Daily quota exceeded (1000 calls/day).",
            "created_at": _iso(now),
            "updated_at": _iso(now),
        })
        _save("api_requests.json", api_requests)
        return _err("QUOTA_EXCEEDED", "Daily quota exceeded.")

    # ---- resolve active server token ----
    for tok in oauth_tokens:
        if tok.get("subject_type") == "server" and tok.get("status") == "active":
            exp = _parse_dt(tok.get("expires_at"))
            if exp and exp <= now:
                tok["status"] = "expired"
                tok["updated_at"] = _iso(now)

    token = None
    for tok in oauth_tokens:
        if tok.get("subject_type") == "server" and tok.get("status") == "active":
            exp = _parse_dt(tok.get("expires_at"))
            if exp and exp > now:
                token = tok
                break
    if not token:
        rid = _new_id("req")
        api_requests.append({
            "id": rid,
            "tool_name": "get_recommendations",
            "oauth_token_id": None,
            "spotify_endpoint": "/v1/recommendations",
            "http_method": "GET",
            "request_params": {
                "seed_tracks_spotify_ids": tracks,
                "seed_artists_spotify_ids": artists,
                "seed_genres": genres,
                "market": market,
                "limit": limit,
                "tunable_attributes": tunable_attributes,
            },
            "response_status_code": None,
            "response_time_ms": int((time.time() - t0) * 1000),
            "result_cache_hit": False,
            "status": "failed",
            "error_message": "No active server OAuth token available.",
            "created_at": _iso(now),
            "updated_at": _iso(now),
        })
        _save("api_requests.json", api_requests)
        _save("oauth_tokens.json", oauth_tokens)
        return _err("UNAUTHORIZED", "No valid Spotify OAuth token available for server requests.")

    # ---- perform offline "recommendations" using available cached tracks ----
    # We must not fabricate tracks; return up to limit from cached catalog_items where entity_type='track'.
    # Prefer tracks that match any provided seed track ids; else arbitrary stable order.
    track_items = [ci for ci in catalog_items if ci.get("entity_type") == "track" and isinstance(ci.get("spotify_id"), str)]
    # stable sort by spotify_id
    track_items.sort(key=lambda x: x.get("spotify_id"))

    seed_set = set(tracks)
    preferred = [ci for ci in track_items if ci.get("spotify_id") in seed_set]
    others = [ci for ci in track_items if ci.get("spotify_id") not in seed_set]
    chosen = (preferred + others)[:limit]

    # If none exist, treat as failure (since we cannot fabricate Spotify response)
    rec_id = _new_id("reco")
    req_row = {
        "id": rec_id,
        "seed_tracks_spotify_ids": tracks if tracks else None,
        "seed_artists_spotify_ids": artists if artists else None,
        "seed_genres": genres if genres else None,
        "market": market,
        "limit": limit,
        "tunable_attributes": tunable_attributes,
        "result_track_catalog_item_ids": None,
        "response_raw_json": None,
        "status": None,
        "error_message": None,
        "created_at": _iso(now),
        "updated_at": _iso(now),
    }

    if len(chosen) == 0:
        req_row["status"] = "failed"
        req_row["error_message"] = "No cached track catalog items available to serve recommendations offline."
        recommendation_requests.append(req_row)

        token["last_used_at"] = _iso(now)
        token["updated_at"] = _iso(now)

        api_requests.append({
            "id": _new_id("req"),
            "tool_name": "get_recommendations",
            "oauth_token_id": token.get("id"),
            "spotify_endpoint": "/v1/recommendations",
            "http_method": "GET",
            "request_params": {
                "seed_tracks_spotify_ids": tracks,
                "seed_artists_spotify_ids": artists,
                "seed_genres": genres,
                "market": market,
                "limit": limit,
                "tunable_attributes": tunable_attributes,
            },
            "response_status_code": 424,
            "response_time_ms": int((time.time() - t0) * 1000),
            "result_cache_hit": False,
            "status": "failed",
            "error_message": req_row["error_message"],
            "created_at": _iso(now),
            "updated_at": _iso(now),
        })

        _save("recommendation_requests.json", recommendation_requests)
        _save("oauth_tokens.json", oauth_tokens)
        _save("api_requests.json", api_requests)
        return _err("NOT_FOUND", "Unable to generate recommendations from local cache; no track data available.")

    result_ids = [ci.get("id") for ci in chosen if ci.get("id")]
    tracks_payload = [ci.get("raw_json") for ci in chosen]

    response_payload = {
        "seeds": [
            *([{"type": "track", "id": x}] for x in tracks),
            *([{"type": "artist", "id": x}] for x in artists),
            *([{"type": "genre", "id": x}] for x in genres),
        ],
        "tracks": tracks_payload,
    }

    req_row["status"] = "completed"
    req_row["result_track_catalog_item_ids"] = result_ids
    req_row["response_raw_json"] = response_payload
    req_row["updated_at"] = _iso(now)
    recommendation_requests.append(req_row)

    token["last_used_at"] = _iso(now)
    token["updated_at"] = _iso(now)

    api_requests.append({
        "id": _new_id("req"),
        "tool_name": "get_recommendations",
        "oauth_token_id": token.get("id"),
        "spotify_endpoint": "/v1/recommendations",
        "http_method": "GET",
        "request_params": {
            "seed_tracks_spotify_ids": tracks,
            "seed_artists_spotify_ids": artists,
            "seed_genres": genres,
            "market": market,
            "limit": limit,
            "tunable_attributes": tunable_attributes,
        },
        "response_status_code": 200,
        "response_time_ms": int((time.time() - t0) * 1000),
        "result_cache_hit": False,
        "status": "succeeded",
        "error_message": None,
        "created_at": _iso(now),
        "updated_at": _iso(now),
    })

    _save("recommendation_requests.json", recommendation_requests)
    _save("oauth_tokens.json", oauth_tokens)
    _save("api_requests.json", api_requests)

    return response_payload

def get_audiobook(audiobook_spotify_id, market=None, **_extra):
    import json, os, datetime, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0062000" if __import__("os").path.isdir("./environment_mix/0062000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    started = datetime.datetime.now(datetime.timezone.utc)

    def _utcnow():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(v, str):
            return None
        s = v.strip()
        if not s:
            return None
        if s.endswith("Z"):
            s = s[:-1] + "+00:00"
        try:
            dt = datetime.datetime.fromisoformat(s)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except ValueError:
            return None

    def _iso(dt):
        if not isinstance(dt, datetime.datetime):
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _ms():
        return max(0, int((_utcnow() - started).total_seconds() * 1000))

    def _new_id(prefix):
        import uuid
        return f"{prefix}_{uuid.uuid4().hex}"

    def _log(status, oauth_token_id=None, result_cache_hit=False, spotify_endpoint=None, http_method=None,
             response_status_code=None, response_time_ms=None, error_message=None, request_params=None):
        now = _utcnow()
        api_requests = _load("api_requests.json")
        api_requests.append({
            "id": _new_id("spt_req"),
            "tool_name": "get_audiobook",
            "oauth_token_id": oauth_token_id,
            "spotify_endpoint": spotify_endpoint,
            "http_method": http_method,
            "request_params": request_params if isinstance(request_params, dict) else {"audiobook_spotify_id": audiobook_spotify_id, "market": market},
            "response_status_code": response_status_code,
            "response_time_ms": response_time_ms,
            "result_cache_hit": bool(result_cache_hit),
            "status": status,
            "error_message": error_message,
            "created_at": _iso(now),
            "updated_at": _iso(now),
        })
        _save("api_requests.json", api_requests)

    # Validate
    if not isinstance(audiobook_spotify_id, str) or not audiobook_spotify_id.strip():
        _log("failed", error_message="audiobook_spotify_id is required")
        return _err("VALIDATION_ERROR", "audiobook_spotify_id is required", audiobook_spotify_id=audiobook_spotify_id)
    audiobook_spotify_id = audiobook_spotify_id.strip()

    if market is not None:
        if not isinstance(market, str) or not re.fullmatch(r"[A-Za-z]{2}", market.strip()):
            _log("failed", error_message="market must be ISO 3166-1 alpha-2")
            return _err("VALIDATION_ERROR", "market must be a valid ISO 3166-1 alpha-2 country code", market=market)
        market = market.strip().upper()

    # Auth: server token
    oauth_tokens = _load("oauth_tokens.json")
    now = _utcnow()
    changed = False
    for tok in oauth_tokens:
        if tok.get("subject_type") == "server" and tok.get("status") == "active":
            exp = _parse_dt(tok.get("expires_at"))
            if exp is not None and exp <= now:
                tok["status"] = "expired"
                tok["updated_at"] = _iso(now)
                changed = True
    if changed:
        _save("oauth_tokens.json", oauth_tokens)

    token = None
    for tok in oauth_tokens:
        if tok.get("subject_type") == "server" and tok.get("status") == "active":
            exp = _parse_dt(tok.get("expires_at"))
            if exp is None or exp > now:
                token = tok
                break
    if token is None:
        _log("failed", error_message="No active OAuth token available for server subject")
        return _err("UNAUTHORIZED", "No active OAuth token available for server subject")

    catalog_items = _load("catalog_items.json")
    now = _utcnow()

    fresh = None
    for it in catalog_items:
        if it.get("entity_type") == "audiobook" and it.get("spotify_id") == audiobook_spotify_id:
            if it.get("cache_status") == "fresh":
                exp = _parse_dt(it.get("expires_at"))
                if exp is not None and exp > now:
                    fresh = it
                    break
    if fresh is not None:
        token["last_used_at"] = _iso(now)
        token["updated_at"] = _iso(now)
        _save("oauth_tokens.json", oauth_tokens)
        _log("succeeded", oauth_token_id=token.get("id"), result_cache_hit=True,
             spotify_endpoint="/v1/audiobooks/{id}", http_method="GET",
             response_status_code=200, response_time_ms=_ms(),
             request_params={"audiobook_spotify_id": audiobook_spotify_id, "market": market})
        return {"audiobook": fresh.get("raw_json")}

    existing = None
    for it in catalog_items:
        if it.get("entity_type") == "audiobook" and it.get("spotify_id") == audiobook_spotify_id:
            existing = it
            break
    if existing is not None and isinstance(existing.get("raw_json"), dict):
        token["last_used_at"] = _iso(now)
        token["updated_at"] = _iso(now)
        _save("oauth_tokens.json", oauth_tokens)
        _log("succeeded", oauth_token_id=token.get("id"), result_cache_hit=True,
             spotify_endpoint="/v1/audiobooks/{id}", http_method="GET",
             response_status_code=200, response_time_ms=_ms(),
             request_params={"audiobook_spotify_id": audiobook_spotify_id, "market": market})
        return {"audiobook": existing.get("raw_json")}

    token["last_used_at"] = _iso(now)
    token["updated_at"] = _iso(now)
    _save("oauth_tokens.json", oauth_tokens)
    _log("failed", oauth_token_id=token.get("id"), result_cache_hit=False,
         spotify_endpoint="/v1/audiobooks/{id}", http_method="GET",
         response_status_code=404, response_time_ms=_ms(),
         error_message="Audiobook not found in local cache (offline mode)",
         request_params={"audiobook_spotify_id": audiobook_spotify_id, "market": market})
    return _err("NOT_FOUND", "Audiobook not found", audiobook_spotify_id=audiobook_spotify_id)

def get_audiobook_chapters(audiobook_spotify_id, market=None, limit=None, offset=None, **_extra):
    import json, os, datetime, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0062000" if __import__("os").path.isdir("./environment_mix/0062000") else "/app/database")
    def _load(n):
