    user_token["updated_at"] = now_iso
    _save("oauth_tokens.json", oauth_tokens)

    endpoint = f"/v1/playlists/{playlist_spotify_id}/items"
    params = {"playlist_spotify_id": playlist_spotify_id, "market": market.strip().upper() if isinstance(market, str) else None, "fields": fields, "limit": limit, "offset": offset, "additional_types": additional_types}
    _log("get_playlist_items", user_token.get("id"), endpoint, "GET", params, True, "succeeded", None, 200, int((time.time() - t0) * 1000))

    return {
        "href": endpoint,
        "items": page_items,
        "limit": limit,
        "next": (f"{endpoint}?offset={next_offset}&limit={limit}" + (f"&market={params['market']}" if params["market"] else "")) if has_more else None,
        "offset": offset,
        "previous": (f"{endpoint}?offset={max(0, offset - limit)}&limit={limit}" + (f"&market={params['market']}" if params["market"] else "")) if offset > 0 else None,
        "total": total,
        "has_more": has_more,
    }

def modify_playlist(playlist_spotify_id, name=None, public=None, collaborative=None, description=None, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0062000" if __import__("os").path.isdir("./environment_mix/0062000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow()

    def _dt_parse(x):
        if x is None:
            return None
        if isinstance(x, datetime.datetime):
            return x
        if isinstance(x, str):
            s = x.strip()
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            try:
                return datetime.datetime.fromisoformat(s).replace(tzinfo=None)
            except Exception:
                return None
        return None

    def _dt_iso(x):
        if isinstance(x, datetime.datetime):
            return x.replace(microsecond=0).isoformat() + "Z"
        return x

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    # Validate inputs
    if not isinstance(playlist_spotify_id, str) or not playlist_spotify_id.strip():
        return _err("VALIDATION_ERROR", "playlist_spotify_id is required and must be a non-empty string")
    if name is not None and not isinstance(name, str):
        return _err("VALIDATION_ERROR", "name must be a string when provided")
    if public is not None and not isinstance(public, bool):
        return _err("VALIDATION_ERROR", "public must be a boolean when provided")
    if collaborative is not None and not isinstance(collaborative, bool):
        return _err("VALIDATION_ERROR", "collaborative must be a boolean when provided")
    if description is not None and not isinstance(description, str):
        return _err("VALIDATION_ERROR", "description must be a string when provided")
    if all(v is None for v in (name, public, collaborative, description)):
        return _err("VALIDATION_ERROR", "At least one of name, public, collaborative, description must be provided")

    oauth_tokens = _load("oauth_tokens.json")
    api_requests = _load("api_requests.json")
    catalog_items = _load("catalog_items.json")
    catalog_links = _load("catalog_links.json")

    def _log(status, *, oauth_token_id=None, endpoint=None, method=None, resp_code=None, resp_ms=None, cache_hit=False, error_message=None):
        rid = _new_id("req")
        row = {
            "id": rid,
            "tool_name": "modify_playlist",
            "oauth_token_id": oauth_token_id,
            "spotify_endpoint": endpoint,
            "http_method": method,
            "request_params": {
                "playlist_spotify_id": playlist_spotify_id,
                **({} if name is None else {"name": name}),
                **({} if public is None else {"public": public}),
                **({} if collaborative is None else {"collaborative": collaborative}),
                **({} if description is None else {"description": description}),
            },
            "response_status_code": resp_code,
            "response_time_ms": resp_ms,
            "result_cache_hit": bool(cache_hit),
            "status": status,
            "error_message": error_message,
            "created_at": _dt_iso(now),
            "updated_at": _dt_iso(now),
        }
        api_requests.append(row)
        _save("api_requests.json", api_requests)

    # Expire past-due active server tokens (rule used by get_access_token, but harmless to enforce here too)
    changed_tokens = False
    for tok in oauth_tokens:
        if tok.get("subject_type") == "server" and tok.get("status") == "active":
            exp = _dt_parse(tok.get("expires_at"))
            if exp is not None and exp <= now:
                tok["status"] = "expired"
                tok["updated_at"] = _dt_iso(now)
                changed_tokens = True
    if changed_tokens:
        _save("oauth_tokens.json", oauth_tokens)

    # Need an active spotify_user token for playlist endpoints
    usable_token = None
    for tok in oauth_tokens:
        if tok.get("subject_type") == "spotify_user" and tok.get("status") == "active":
            exp = _dt_parse(tok.get("expires_at"))
            if exp is None or exp > now:
                usable_token = tok
                break
    if usable_token is None:
        _log("failed", oauth_token_id=None, endpoint=None, method=None, resp_code=None, resp_ms=int((time.time()-t0)*1000), cache_hit=False, error_message="No active spotify_user OAuth token available")
        return _err("UNAUTHORIZED", "No active Spotify OAuth session available for the current user")

    # Find playlist catalog item
    playlist_item = None
    for it in catalog_items:
        if it.get("entity_type") == "playlist" and it.get("spotify_id") == playlist_spotify_id:
            playlist_item = it
            break
    if playlist_item is None:
        _log("failed", oauth_token_id=usable_token.get("id"), endpoint="/v1/playlists/{playlist_id}", method="PUT", resp_code=404, resp_ms=int((time.time()-t0)*1000), cache_hit=False, error_message="Playlist not found in catalog cache")
        return _err("NOT_FOUND", "Playlist not found", playlist_spotify_id=playlist_spotify_id)

    # Simulate Spotify update success by mutating cached raw_json + fields; enforce "no success without effect"
    raw = playlist_item.get("raw_json")
    if not isinstance(raw, dict):
        raw = {}

    before = {
        "name": playlist_item.get("name"),
        "is_public": playlist_item.get("is_public"),
        "description_text": playlist_item.get("description_text"),
        "raw_name": raw.get("name"),
        "raw_public": raw.get("public"),
        "raw_collaborative": raw.get("collaborative"),
        "raw_description": raw.get("description"),
    }

    if name is not None:
        playlist_item["name"] = name
        raw["name"] = name
    if public is not None:
        playlist_item["is_public"] = public
        raw["public"] = public
    if collaborative is not None:
        raw["collaborative"] = collaborative
    if description is not None:
        playlist_item["description_text"] = description
        raw["description"] = description

    after = {
        "name": playlist_item.get("name"),
        "is_public": playlist_item.get("is_public"),
        "description_text": playlist_item.get("description_text"),
        "raw_name": raw.get("name"),
        "raw_public": raw.get("public"),
        "raw_collaborative": raw.get("collaborative"),
        "raw_description": raw.get("description"),
    }

    if before == after:
        _log("failed", oauth_token_id=usable_token.get("id"), endpoint="/v1/playlists/{playlist_id}", method="PUT", resp_code=409, resp_ms=int((time.time()-t0)*1000), cache_hit=False, error_message="No changes to apply")
        return _err("CONFLICT", "No changes to apply")

    # Update snapshot id
    new_snapshot_id = "snap_" + uuid.uuid4().hex
    raw["snapshot_id"] = new_snapshot_id
    playlist_item["raw_json"] = raw

    # Refresh cache timestamps for playlist
    playlist_item["cache_status"] = "fresh"
    playlist_item["cached_at"] = _dt_iso(now)
    # TTL heuristic for playlists
    playlist_item["expires_at"] = _dt_iso(now + datetime.timedelta(minutes=15))
    playlist_item["updated_at"] = _dt_iso(now)

    # Business rule: after successful modification, stale playlist_item links
    any_link_changed = False
    for l in catalog_links:
        if l.get("link_type") == "playlist_item" and l.get("from_catalog_item_id") == playlist_item.get("id") and l.get("status") == "active":
            l["status"] = "deleted"  # mark stale
            l["snapshot_id"] = new_snapshot_id
            l["updated_at"] = _dt_iso(now)
            any_link_changed = True

    _save("catalog_items.json", catalog_items)
    if any_link_changed:
        _save("catalog_links.json", catalog_links)

    usable_token["last_used_at"] = _dt_iso(now)
    usable_token["updated_at"] = _dt_iso(now)
    _save("oauth_tokens.json", oauth_tokens)

    _log("succeeded", oauth_token_id=usable_token.get("id"), endpoint="/v1/playlists/{playlist_id}", method="PUT", resp_code=200, resp_ms=int((time.time()-t0)*1000), cache_hit=False, error_message=None)

    return {
        "playlist_spotify_id": playlist_spotify_id,
        "snapshot_id": new_snapshot_id,
        "playlist": playlist_item.get("raw_json"),
        "cache": {"updated": True, "staled_playlist_items_links": bool(any_link_changed)},
    }

def add_tracks_to_playlist(playlist_spotify_id, uris, position=None, **_extra):
    import json, os, datetime, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0062000" if __import__("os").path.isdir("./environment_mix/0062000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    started = datetime.datetime.now(datetime.timezone.utc)

    def _utcnow():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(v, str):
            return None
        s = v.strip()
        if not s:
            return None
        if s.endswith("Z"):
            s = s[:-1] + "+00:00"
        try:
            dt = datetime.datetime.fromisoformat(s)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except ValueError:
            return None

    def _iso(dt):
        if not isinstance(dt, datetime.datetime):
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _ms():
        return max(0, int((_utcnow() - started).total_seconds() * 1000))

    def _new_id(prefix):
        import uuid
        return f"{prefix}_{uuid.uuid4().hex}"

    def _log(status, oauth_token_id=None, result_cache_hit=False, spotify_endpoint=None, http_method=None,
             response_status_code=None, response_time_ms=None, error_message=None, request_params=None):
        now = _utcnow()
        api_requests = _load("api_requests.json")
        api_requests.append({
            "id": _new_id("spt_req"),
            "tool_name": "add_tracks_to_playlist",
            "oauth_token_id": oauth_token_id,
            "spotify_endpoint": spotify_endpoint,
            "http_method": http_method,
            "request_params": request_params if isinstance(request_params, dict) else {
                "playlist_spotify_id": playlist_spotify_id, "uris": uris, "position": position
            },
            "response_status_code": response_status_code,
            "response_time_ms": response_time_ms,
            "result_cache_hit": bool(result_cache_hit),
            "status": status,
            "error_message": error_message,
            "created_at": _iso(now),
            "updated_at": _iso(now),
        })
        _save("api_requests.json", api_requests)

    # Validate inputs
    if not isinstance(playlist_spotify_id, str) or not playlist_spotify_id.strip():
        _log("failed", error_message="playlist_spotify_id is required")
        return _err("VALIDATION_ERROR", "playlist_spotify_id is required", playlist_spotify_id=playlist_spotify_id)
    playlist_spotify_id = playlist_spotify_id.strip()

    if not isinstance(uris, list) or len(uris) < 1:
        _log("failed", error_message="uris must be a non-empty array")
        return _err("VALIDATION_ERROR", "uris must be a non-empty array", uris=uris)

    track_uri_re = re.compile(r"^spotify:track:[A-Za-z0-9]+$")
    for u in uris:
        if not isinstance(u, str) or not u.strip():
            _log("failed", error_message="All uris must be non-empty strings")
            return _err("VALIDATION_ERROR", "All uris must be non-empty strings", uris=uris)
        if not track_uri_re.fullmatch(u.strip()):
            _log("failed", error_message="All uris must be Spotify track URIs of the form spotify:track:<id>")
            return _err("VALIDATION_ERROR", "All uris must be Spotify track URIs of the form spotify:track:<id>", uri=u)

    if position is not None:
        if not isinstance(position, int) or position < 0:
            _log("failed", error_message="position must be an integer >= 0 when provided")
            return _err("VALIDATION_ERROR", "position must be an integer >= 0 when provided", position=position)

    # Auth: spotify_user token required for playlist mutation
    oauth_tokens = _load("oauth_tokens.json")
    now = _utcnow()
    changed = False
    for tok in oauth_tokens:
        if tok.get("subject_type") == "spotify_user" and tok.get("status") == "active":
            exp = _parse_dt(tok.get("expires_at"))
            if exp is not None and exp <= now:
                tok["status"] = "expired"
                tok["updated_at"] = _iso(now)
                changed = True
    if changed:
        _save("oauth_tokens.json", oauth_tokens)

    token = None
    for tok in oauth_tokens:
        if tok.get("subject_type") == "spotify_user" and tok.get("status") == "active":
            exp = _parse_dt(tok.get("expires_at"))
            if exp is None or exp > now:
                token = tok
                break
    if token is None:
        _log("failed", error_message="No active OAuth token available for spotify_user subject")
        return _err("UNAUTHORIZED", "No active OAuth token available for spotify_user subject")

    # Must operate on a playlist catalog_item
    catalog_items = _load("catalog_items.json")
    playlist_item = None
    for it in catalog_items:
        if it.get("entity_type") == "playlist" and it.get("spotify_id") == playlist_spotify_id:
            playlist_item = it
            break
    if playlist_item is None:
        token["last_used_at"] = _iso(now)
        token["updated_at"] = _iso(now)
        _save("oauth_tokens.json", oauth_tokens)
        _log("failed", oauth_token_id=token.get("id"), error_message="Playlist not found in local catalog_items",
             spotify_endpoint="/v1/playlists/{id}/tracks", http_method="POST",
             response_status_code=404, response_time_ms=_ms())
        return _err("NOT_FOUND", "Playlist not found", playlist_spotify_id=playlist_spotify_id)

    # Ensure referenced tracks exist as catalog_items rows (offline "upsert" without inventing payload)
    # If a track is not present, reject (can't call Spotify to resolve).
    spotify_track_ids = [u.split(":")[-1] for u in uris]
    track_items_by_spid = {}
    for it in catalog_items:
        if it.get("entity_type") == "track" and it.get("spotify_id") in spotify_track_ids:
            track_items_by_spid[it.get("spotify_id")] = it
    missing = [tid for tid in spotify_track_ids if tid not in track_items_by_spid]
    if missing:
        token["last_used_at"] = _iso(now)
        token["updated_at"] = _iso(now)
        _save("oauth_tokens.json", oauth_tokens)
        _log("failed", oauth_token_id=token.get("id"),
             error_message="One or more track IDs are not present in local catalog_items (offline mode)",
             spotify_endpoint="/v1/playlists/{id}/tracks", http_method="POST",
             response_status_code=404, response_time_ms=_ms(),
             request_params={"playlist_spotify_id": playlist_spotify_id, "uris": uris, "position": position, "missing_track_ids": missing})
        return _err("NOT_FOUND", "One or more tracks not found", missing_track_ids=missing)

    catalog_links = _load("catalog_links.json")

    # Existing active playlist items
    existing_links = [l for l in catalog_links if l.get("link_type") == "playlist_item" and l.get("from_catalog_item_id") == playlist_item.get("id") and l.get("status") == "active"]
    existing_links.sort(key=lambda x: (x.get("position") is None, x.get("position") if x.get("position") is not None else 10**9, x.get("id", "")))

    # Modification: mark existing active playlist items as deleted (stale) per business rules
    now_iso = _iso(now)
    for l in existing_links:
        l["status"] = "deleted"
        l["updated_at"] = now_iso

    # Create new snapshot id and new active links
    import uuid
    new_snapshot = uuid.uuid4().hex
    insert_at = position if position is not None else len(existing_links)
    insert_at = max(0, min(insert_at, len(existing_links)))

    # Build resulting sequence
    kept_deleted = existing_links[:]  # already marked deleted; used for ordering base
    new_sequence_ids = []
    for l in kept_deleted:
        new_sequence_ids.append(l.get("to_catalog_item_id"))

    # Insert track catalog_item ids
    to_add_ids = [track_items_by_spid[tid].get("id") for tid in spotify_track_ids]
    new_sequence_ids[insert_at:insert_at] = to_add_ids

    # Upsert new active links for full current list with proper positions and snapshot_id
    # (We keep deleted ones for audit; new actives reflect the refreshed snapshot.)
    for pos, to_id in enumerate(new_sequence_ids):
        new_link = {
            "id": _new_id("spt_lnk"),
            "link_type": "playlist_item",
            "from_catalog_item_id": playlist_item.get("id"),
            "to_catalog_item_id": to_id,
            "position": pos,
            "added_at": now_iso,
            "added_by_spotify_user_id": token.get("spotify_user_id"),
            "snapshot_id": new_snapshot,
            "market": None,
            "metadata": None,
            "status": "active",
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        catalog_links.append(new_link)

    _save("catalog_links.json", catalog_links)

    token["last_used_at"] = now_iso
    token["updated_at"] = now_iso
    _save("oauth_tokens.json", oauth_tokens)

    _log("succeeded", oauth_token_id=token.get("id"), result_cache_hit=False,
         spotify_endpoint="/v1/playlists/{id}/tracks", http_method="POST",
         response_status_code=201, response_time_ms=_ms(),
         request_params={"playlist_spotify_id": playlist_spotify_id, "uris": uris, "position": position})

    return {"snapshot_id": new_snapshot, "playlist_spotify_id": playlist_spotify_id}

