                break
    if usable_token is None:
        _log("failed", oauth_token_id=None, endpoint=None, method=None, resp_code=None, resp_ms=int((time.time()-t0)*1000), cache_hit=False, error_message="No active spotify_user OAuth token available")
        return _err("UNAUTHORIZED", "No active Spotify OAuth session available for the current user")

    # Find playlist
    playlist_item = None
    for it in catalog_items:
        if it.get("entity_type") == "playlist" and it.get("spotify_id") == playlist_spotify_id:
            playlist_item = it
            break
    if playlist_item is None:
        _log("failed", oauth_token_id=usable_token.get("id"), endpoint="/v1/playlists/{playlist_id}/tracks", method="DELETE", resp_code=404, resp_ms=int((time.time()-t0)*1000), cache_hit=False, error_message="Playlist not found in catalog cache")
        return _err("NOT_FOUND", "Playlist not found", playlist_spotify_id=playlist_spotify_id)

    raw = playlist_item.get("raw_json")
    if not isinstance(raw, dict):
        raw = {}
    current_snapshot = raw.get("snapshot_id")

    # optimistic concurrency if snapshot_id provided
    if snapshot_id is not None and current_snapshot is not None and snapshot_id != current_snapshot:
        _log("failed", oauth_token_id=usable_token.get("id"), endpoint="/v1/playlists/{playlist_id}/tracks", method="DELETE", resp_code=409, resp_ms=int((time.time()-t0)*1000), cache_hit=False, error_message="Snapshot mismatch")
        return _err("CONFLICT", "snapshot_id does not match current playlist snapshot", current_snapshot_id=current_snapshot)

    # NO SUCCESS WITHOUT EFFECT: require at least one active playlist_item link to delete (we don't track full occurrences precisely)
    playlist_id = playlist_item.get("id")
    active_links = [l for l in catalog_links if l.get("link_type") == "playlist_item" and l.get("from_catalog_item_id") == playlist_id and l.get("status") == "active"]
    if len(active_links) == 0:
        _log("failed", oauth_token_id=usable_token.get("id"), endpoint="/v1/playlists/{playlist_id}/tracks", method="DELETE", resp_code=404, resp_ms=int((time.time()-t0)*1000), cache_hit=False, error_message="No active playlist items to remove (cache empty/stale)")
        return _err("NOT_FOUND", "No cached active playlist items found to remove; refresh playlist items first")

    # Mark playlist items stale/deleted (rule)
    for l in active_links:
        l["status"] = "deleted"
        l["updated_at"] = _dt_iso(now)

    # Update playlist snapshot id and cache metadata
    new_snapshot_id = "snap_" + uuid.uuid4().hex
    raw["snapshot_id"] = new_snapshot_id
    playlist_item["raw_json"] = raw
    playlist_item["cache_status"] = "fresh"
    playlist_item["cached_at"] = _dt_iso(now)
    playlist_item["expires_at"] = _dt_iso(now + datetime.timedelta(minutes=15))
    playlist_item["updated_at"] = _dt_iso(now)

    _save("catalog_links.json", catalog_links)
    _save("catalog_items.json", catalog_items)

    usable_token["last_used_at"] = _dt_iso(now)
    usable_token["updated_at"] = _dt_iso(now)
    _save("oauth_tokens.json", oauth_tokens)

    _log("succeeded", oauth_token_id=usable_token.get("id"), endpoint="/v1/playlists/{playlist_id}/tracks", method="DELETE", resp_code=200, resp_ms=int((time.time()-t0)*1000), cache_hit=False, error_message=None)

    return {
        "playlist_spotify_id": playlist_spotify_id,
        "snapshot_id": new_snapshot_id,
        "previous_snapshot_id": current_snapshot,
        "staled_playlist_items_links": True,
        "removed_request": {"tracks": tracks},
    }

