        return dt.astimezone(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(v, str):
            return None
        s = v.strip()
        if not s:
            return None
        if s.endswith("Z"):
            s = s[:-1] + "+00:00"
        try:
            dt = datetime.datetime.fromisoformat(s)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    def _new_id(prefix):
        import uuid
        return f"{prefix}_{uuid.uuid4().hex}"

    def _ms_since(start_dt):
        dt = _utcnow()
        return max(0, int((dt - start_dt).total_seconds() * 1000))

    def _select_token(oauth_tokens, subject_type, spotify_user_id=None):
        now = _utcnow()
        changed = False
        for tok in oauth_tokens:
            if tok.get("subject_type") == subject_type and tok.get("status") == "active":
                exp = _parse_dt(tok.get("expires_at"))
                if exp is not None and exp <= now:
                    tok["status"] = "expired"
                    tok["updated_at"] = _iso(now)
                    changed = True
        if changed:
            _save("oauth_tokens.json", oauth_tokens)

        candidates = []
        for tok in oauth_tokens:
            if tok.get("subject_type") != subject_type:
                continue
            if tok.get("status") != "active":
                continue
            exp = _parse_dt(tok.get("expires_at"))
            if exp is not None and exp <= now:
                continue
            if subject_type == "spotify_user" and spotify_user_id is not None:
                if tok.get("spotify_user_id") != spotify_user_id:
                    continue
            candidates.append(tok)
        if not candidates:
            return None
        candidates.sort(key=lambda r: (len(r.get("scope") or []), (_parse_dt(r.get("expires_at")) or now)), reverse=True)
        return candidates[0]

    def _log(tool_status, *, oauth_token_id=None, error_message=None, response_status_code=None):
        api_requests = _load("api_requests.json")
        now = _utcnow()
        api_requests.append({
            "id": _new_id("spt_req"),
            "tool_name": "get_current_identity",
            "oauth_token_id": oauth_token_id,
            "spotify_endpoint": None,
            "http_method": None,
            "request_params": {"subject_type": subject_type, "spotify_user_id": spotify_user_id},
            "response_status_code": response_status_code,
            "response_time_ms": _ms_since(t0),
            "result_cache_hit": False,
            "status": tool_status,
            "error_message": error_message,
            "created_at": _iso(now),
            "updated_at": _iso(now),
        })
        _save("api_requests.json", api_requests)

    if subject_type not in ("server", "spotify_user"):
        _log("failed", response_status_code=400, error_message="Invalid subject_type")
        return _err("VALIDATION_ERROR", "Invalid subject_type; must be 'server' or 'spotify_user'")
    if subject_type == "spotify_user" and spotify_user_id is not None and (not isinstance(spotify_user_id, str) or not spotify_user_id.strip()):
        _log("failed", response_status_code=400, error_message="spotify_user_id must be a non-empty string when provided")
        return _err("VALIDATION_ERROR", "spotify_user_id must be a non-empty string when provided")
    if isinstance(spotify_user_id, str):
        spotify_user_id = spotify_user_id.strip()

    oauth_tokens = _load("oauth_tokens.json")
    tok = _select_token(oauth_tokens, subject_type, spotify_user_id=spotify_user_id)
    if tok is None:
        _log("failed", response_status_code=401, error_message="No active OAuth token available for requested subject")
        return _err("UNAUTHORIZED", "No active OAuth token available for requested subject", subject_type=subject_type, spotify_user_id=spotify_user_id)

    # quota/rate derived from audit log (simple rolling window counts)
    api_requests = _load("api_requests.json")
    now = _utcnow()
    window_1m = now - datetime.timedelta(minutes=1)
    window_1h = now - datetime.timedelta(hours=1)

    def _row_time(r):
        return _parse_dt(r.get("created_at")) or _parse_dt(r.get("updated_at"))

    last_1m = 0
    last_1h = 0
    for r in api_requests:
        rt = _row_time(r)
        if rt is None:
            continue
        if rt >= window_1m:
            last_1m += 1
        if rt >= window_1h:
            last_1h += 1

    now2 = _utcnow()
    for t in oauth_tokens:
        if t.get("id") == tok.get("id"):
            t["last_used_at"] = _iso(now2)
            t["updated_at"] = _iso(now2)
            break
    _save("oauth_tokens.json", oauth_tokens)

    _log("succeeded", oauth_token_id=tok.get("id"), response_status_code=200)
    return {
        "subject_type": subject_type,
        "spotify_user_id": tok.get("spotify_user_id") if subject_type == "spotify_user" else None,
        "oauth_token": {
            "id": tok.get("id"),
            "token_type": tok.get("token_type"),
            "status": tok.get("status"),
            "expires_at": tok.get("expires_at"),
            "scope": tok.get("scope") or [],
            "last_used_at": tok.get("last_used_at"),
        },
        "usage": {
            "requests_last_1m": last_1m,
            "requests_last_1h": last_1h,
            "audit_log_rows_total": len(api_requests),
        },
    }

def list_oauth_tokens(subject_type=None, spotify_user_id=None, status=None, limit=None, offset=None, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0062000" if __import__("os").path.isdir("./environment_mix/0062000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)

    def _dt_parse(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s.strip():
            return None
        ss = s.strip()
        try:
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(ss)
        except ValueError:
            return None

    def _iso(dt):
        if dt is None:
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat()

    def _gen_id(prefix):
        import uuid
        return f"{prefix}_{uuid.uuid4().hex}"

    def _log(api_requests, tool_name, oauth_token_id, request_params, status_s, error_message=None,
             spotify_endpoint=None, http_method=None, response_status_code=None, response_time_ms=None, result_cache_hit=False):
        row = {
            "id": _gen_id("req"),
            "tool_name": tool_name,
            "oauth_token_id": oauth_token_id,
            "spotify_endpoint": spotify_endpoint,
            "http_method": http_method,
            "request_params": request_params,
            "response_status_code": response_status_code,
            "response_time_ms": response_time_ms,
            "result_cache_hit": bool(result_cache_hit),
            "status": status_s,
            "error_message": error_message,
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        api_requests.append(row)
        _save("api_requests.json", api_requests)

    # Validate filters
    if subject_type is not None and subject_type not in ("server", "spotify_user"):
        api_requests = _load("api_requests.json")
        _log(api_requests, "list_oauth_tokens", None,
             {"subject_type": subject_type, "spotify_user_id": spotify_user_id, "status": status, "limit": limit, "offset": offset},
             "failed", "Invalid subject_type filter.")
        return _err("VALIDATION_ERROR", "Invalid subject_type; must be 'server' or 'spotify_user'.")

    if status is not None and status not in ("active", "expired", "revoked"):
        api_requests = _load("api_requests.json")
        _log(api_requests, "list_oauth_tokens", None,
             {"subject_type": subject_type, "spotify_user_id": spotify_user_id, "status": status, "limit": limit, "offset": offset},
             "failed", "Invalid status filter.")
        return _err("VALIDATION_ERROR", "Invalid status; must be 'active', 'expired', or 'revoked'.")

    if spotify_user_id is not None:
        if not isinstance(spotify_user_id, str) or not spotify_user_id.strip():
            api_requests = _load("api_requests.json")
            _log(api_requests, "list_oauth_tokens", None,
                 {"subject_type": subject_type, "spotify_user_id": spotify_user_id, "status": status, "limit": limit, "offset": offset},
                 "failed", "Invalid spotify_user_id filter.")
            return _err("VALIDATION_ERROR", "spotify_user_id must be a non-empty string when provided.")
        if subject_type is not None and subject_type != "spotify_user":
            api_requests = _load("api_requests.json")
            _log(api_requests, "list_oauth_tokens", None,
                 {"subject_type": subject_type, "spotify_user_id": spotify_user_id, "status": status, "limit": limit, "offset": offset},
                 "failed", "spotify_user_id filter is only valid when subject_type=spotify_user.")
            return _err("VALIDATION_ERROR", "spotify_user_id filter is only valid when subject_type=spotify_user.")
        spotify_user_id = spotify_user_id.strip()

    if limit is None:
        limit = 50
    if offset is None:
        offset = 0
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        api_requests = _load("api_requests.json")
        _log(api_requests, "list_oauth_tokens", None,
             {"subject_type": subject_type, "spotify_user_id": spotify_user_id, "status": status, "limit": limit, "offset": offset},
             "failed", "Invalid limit; must be integer between 1 and 200.")
        return _err("VALIDATION_ERROR", "Invalid limit; must be integer between 1 and 200.")
    if not isinstance(offset, int) or offset < 0:
        api_requests = _load("api_requests.json")
        _log(api_requests, "list_oauth_tokens", None,
             {"subject_type": subject_type, "spotify_user_id": spotify_user_id, "status": status, "limit": limit, "offset": offset},
             "failed", "Invalid offset; must be integer >= 0.")
        return _err("VALIDATION_ERROR", "Invalid offset; must be integer >= 0.")

    # Rate limit/quota from api_requests
    api_requests = _load("api_requests.json")
    window_sec = 10
    rate_limit = 50
    quota_day = 10000

    recent = 0
    day = 0
    for r in api_requests:
        dt = _dt_parse(r.get("created_at"))
        if not dt:
            continue
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        dt = dt.astimezone(datetime.timezone.utc)
        delta = (now - dt).total_seconds()
        if 0 <= delta <= window_sec:
            recent += 1
        if 0 <= delta <= 86400:
            day += 1
    if recent >= rate_limit:
        _log(api_requests, "list_oauth_tokens", None,
             {"subject_type": subject_type, "spotify_user_id": spotify_user_id, "status": status, "limit": limit, "offset": offset},
             "failed", "Rate limit exceeded.")
        return _err("RATE_LIMIT", "Rate limit exceeded.", retry_after_seconds=window_sec)
    if day >= quota_day:
        _log(api_requests, "list_oauth_tokens", None,
             {"subject_type": subject_type, "spotify_user_id": spotify_user_id, "status": status, "limit": limit, "offset": offset},
             "failed", "Daily quota exceeded.")
        return _err("QUOTA_EXCEEDED", "Daily quota exceeded.", quota=quota_day, used=day)

    tokens = _load("oauth_tokens.json")

    # Expire past-due active tokens (keeps lifecycle honest; allowed transition active->expired)
    changed = False
    for tok in tokens:
        if tok.get("status") == "active":
            exp = _dt_parse(tok.get("expires_at"))
            if exp:
                if exp.tzinfo is None:
                    exp = exp.replace(tzinfo=datetime.timezone.utc)
                exp = exp.astimezone(datetime.timezone.utc)
                if exp <= now:
                    tok["status"] = "expired"
                    tok["updated_at"] = _iso(now)
                    changed = True
    if changed:
        _save("oauth_tokens.json", tokens)

    # Filter
    rows = []
    for tok in tokens:
        if subject_type is not None and tok.get("subject_type") != subject_type:
            continue
        if status is not None and tok.get("status") != status:
            continue
        if spotify_user_id is not None and tok.get("spotify_user_id") != spotify_user_id:
            continue
        rows.append(tok)

    # Sort by updated_at desc then created_at desc
    def _sort_key(t):
        ua = _dt_parse(t.get("updated_at")) or datetime.datetime.fromtimestamp(0, tz=datetime.timezone.utc)
        ca = _dt_parse(t.get("created_at")) or datetime.datetime.fromtimestamp(0, tz=datetime.timezone.utc)
        if ua.tzinfo is None:
            ua = ua.replace(tzinfo=datetime.timezone.utc)
        if ca.tzinfo is None:
            ca = ca.replace(tzinfo=datetime.timezone.utc)
        return (ua, ca)

    rows.sort(key=_sort_key, reverse=True)

    total = len(rows)
    page = rows[offset:offset + limit]
    has_more = offset + limit < total
    next_offset = offset + limit if has_more else None

    resp = {
        "items": page,
        "limit": limit,
        "offset": offset,
        "total": total,
        "has_more": has_more,
        "next_offset": next_offset
    }

    latency_ms = int((time.time() - t0) * 1000)
    _log(api_requests, "list_oauth_tokens", None,
         {"subject_type": subject_type, "spotify_user_id": spotify_user_id, "status": status, "limit": limit, "offset": offset},
         "succeeded", response_time_ms=latency_ms, result_cache_hit=True)

    return resp

def update_oauth_token(id, status=None, last_used_at=None, expires_at=None, scope=None, **_extra):
    import json, os, datetime, time, uuid, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0062000" if __import__("os").path.isdir("./environment_mix/0062000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_rfc3339(s):
        if not isinstance(s, str) or not s.strip():
            return None, "must be an RFC3339 string"
        v = s.strip()
        try:
            if v.endswith("Z"):
                v2 = v[:-1] + "+00:00"
            else:
                v2 = v
            dt = datetime.datetime.fromisoformat(v2)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc), None
        except Exception:
            return None, "must be an RFC3339 timestamp"

    def _log_request(req_rows, oauth_token_id, req_params, status_val, error_message=None):
        now = _now()
        row = {
            "id": "req_" + uuid.uuid4().hex,
            "tool_name": "update_oauth_token",
            "oauth_token_id": oauth_token_id,
            "spotify_endpoint": None,
            "http_method": None,
            "request_params": req_params,
            "response_status_code": None,
            "response_time_ms": 0,
            "result_cache_hit": True,
            "status": status_val,
            "error_message": error_message,
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        req_rows.append(row)
        return row

    t0 = time.time()

    # Validate inputs
    if not isinstance(id, str) or not id.strip():
        api_requests = _load("api_requests.json")
        _log_request(api_requests, None, {"id": id, "status": status, "last_used_at": last_used_at, "expires_at": expires_at, "scope": scope}, "failed", "id is required and must be a non-empty string")
        _save("api_requests.json", api_requests)
        return _err("VALIDATION_ERROR", "id is required and must be a non-empty string")

    allowed_status = {"active", "expired", "revoked"}
    if status is not None:
        if not isinstance(status, str) or status not in allowed_status:
            api_requests = _load("api_requests.json")
            _log_request(api_requests, None, {"id": id, "status": status, "last_used_at": last_used_at, "expires_at": expires_at, "scope": scope}, "failed", "invalid status")
            _save("api_requests.json", api_requests)
            return _err("VALIDATION_ERROR", "Invalid status", allowed=list(sorted(allowed_status)))

    parsed_last_used = None
    if last_used_at is not None:
        dt, e = _parse_rfc3339(last_used_at)
        if e:
            api_requests = _load("api_requests.json")
            _log_request(api_requests, None, {"id": id, "status": status, "last_used_at": last_used_at, "expires_at": expires_at, "scope": scope}, "failed", "invalid last_used_at")
            _save("api_requests.json", api_requests)
            return _err("VALIDATION_ERROR", "Invalid last_used_at: " + e)
        parsed_last_used = dt

    parsed_expires = None
    if expires_at is not None:
        dt, e = _parse_rfc3339(expires_at)
        if e:
            api_requests = _load("api_requests.json")
            _log_request(api_requests, None, {"id": id, "status": status, "last_used_at": last_used_at, "expires_at": expires_at, "scope": scope}, "failed", "invalid expires_at")
            _save("api_requests.json", api_requests)
            return _err("VALIDATION_ERROR", "Invalid expires_at: " + e)
        parsed_expires = dt

    scope_arr = None
    if scope is not None:
        if not isinstance(scope, str):
            api_requests = _load("api_requests.json")
            _log_request(api_requests, None, {"id": id, "status": status, "last_used_at": last_used_at, "expires_at": expires_at, "scope": scope}, "failed", "scope must be a string")
            _save("api_requests.json", api_requests)
            return _err("VALIDATION_ERROR", "scope must be a string (space-delimited)")
        scope_arr = [p for p in scope.strip().split(" ") if p]
        if scope_arr == []:
            scope_arr = []

    oauth_tokens = _load("oauth_tokens.json")
    tok = None
    for r in oauth_tokens:
        if isinstance(r, dict) and r.get("id") == id:
            tok = r
            break

    api_requests = _load("api_requests.json")

    if tok is None:
        _log_request(api_requests, None, {"id": id, "status": status, "last_used_at": last_used_at, "expires_at": expires_at, "scope": scope}, "failed", "oauth token not found")
        # set latency
        api_requests[-1]["response_time_ms"] = int((time.time() - t0) * 1000)
        api_requests[-1]["updated_at"] = _iso(_now())
        _save("api_requests.json", api_requests)
        return _err("NOT_FOUND", "oauth_tokens row not found", id=id)

    # Enforce lifecycle transitions
    transitions = {
        "active": {"expired", "revoked"},
        "expired": {"active", "revoked"},
        "revoked": set(),
    }
    if status is not None and status != tok.get("status"):
        cur = tok.get("status")
        if cur not in transitions or status not in transitions[cur]:
            _log_request(api_requests, tok.get("id"), {"id": id, "status": status, "last_used_at": last_used_at, "expires_at": expires_at, "scope": scope}, "failed", "invalid status transition")
            api_requests[-1]["response_time_ms"] = int((time.time() - t0) * 1000)
            api_requests[-1]["updated_at"] = _iso(_now())
            _save("api_requests.json", api_requests)
            return _err("INVALID_TRANSITION", f"Invalid status transition {cur} -> {status}")

    # Enforce constraints & uniqueness (only for setting to active)
    if status == "active" and tok.get("status") != "active":
        subj_type = tok.get("subject_type")
        user_id = tok.get("spotify_user_id")
        for r in oauth_tokens:
            if r.get("id") != tok.get("id") and r.get("status") == "active" and r.get("subject_type") == subj_type and r.get("spotify_user_id") == user_id:
                _log_request(api_requests, tok.get("id"), {"id": id, "status": status, "last_used_at": last_used_at, "expires_at": expires_at, "scope": scope}, "failed", "conflict: another active token exists for subject")
                api_requests[-1]["response_time_ms"] = int((time.time() - t0) * 1000)
                api_requests[-1]["updated_at"] = _iso(_now())
                _save("api_requests.json", api_requests)
                return _err("CONFLICT", "An active token already exists for this subject", subject_type=subj_type, spotify_user_id=user_id)

    # Apply updates
    now = _now()
    changed = False

    if status is not None and status != tok.get("status"):
        tok["status"] = status
        changed = True

    if parsed_last_used is not None:
        tok["last_used_at"] = _iso(parsed_last_used)
        changed = True

    if parsed_expires is not None:
        # constraint: expires_at > created_at
        created_at_raw = tok.get("created_at")
        created_dt = None
        if isinstance(created_at_raw, str):
            created_dt, _ = _parse_rfc3339(created_at_raw)
        if created_dt is not None and not (parsed_expires > created_dt):
            _log_request(api_requests, tok.get("id"), {"id": id, "status": status, "last_used_at": last_used_at, "expires_at": expires_at, "scope": scope}, "failed", "expires_at must be > created_at")
            api_requests[-1]["response_time_ms"] = int((time.time() - t0) * 1000)
            api_requests[-1]["updated_at"] = _iso(_now())
            _save("api_requests.json", api_requests)
            return _err("VALIDATION_ERROR", "expires_at must be greater than created_at")
        tok["expires_at"] = _iso(parsed_expires)
        changed = True

    if scope_arr is not None:
        tok["scope"] = scope_arr
        changed = True

    # validate subject constraint
    if tok.get("subject_type") == "spotify_user" and not tok.get("spotify_user_id"):
        _log_request(api_requests, tok.get("id"), {"id": id, "status": status, "last_used_at": last_used_at, "expires_at": expires_at, "scope": scope}, "failed", "spotify_user tokens must have spotify_user_id")
        api_requests[-1]["response_time_ms"] = int((time.time() - t0) * 1000)
        api_requests[-1]["updated_at"] = _iso(_now())
        _save("api_requests.json", api_requests)
        return _err("VALIDATION_ERROR", "subject_type='spotify_user' requires spotify_user_id")

    if not changed:
        # No success without effect
        _log_request(api_requests, tok.get("id"), {"id": id, "status": status, "last_used_at": last_used_at, "expires_at": expires_at, "scope": scope}, "failed", "no fields to update")
        api_requests[-1]["response_time_ms"] = int((time.time() - t0) * 1000)
        api_requests[-1]["updated_at"] = _iso(_now())
        _save("api_requests.json", api_requests)
        return _err("VALIDATION_ERROR", "No updates supplied")

    tok["updated_at"] = _iso(now)
    _save("oauth_tokens.json", oauth_tokens)

    # Log request
