            api_requests[-1]["updated_at"] = _iso(_now())
            _save("api_requests.json", api_requests)
            return _err("VALIDATION_ERROR", f"{k} must be a string")

    if limit is None:
        limit = 50
    if offset is None:
        offset = 0
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        api_requests = _load("api_requests.json")
        _log_request(api_requests, "failed", "invalid limit", {
            "entity_type": entity_type, "spotify_id": spotify_id, "cache_status": cache_status,
