            "entity_type": entity_type, "spotify_id": spotify_id, "cache_status": cache_status,
            "owner_spotify_user_id": owner_spotify_user_id, "q_name": q_name, "limit": limit, "offset": offset
        })
        api_requests[-1]["response_time_ms"] = int((time.time() - t0) * 1000)
        api_requests[-1]["updated_at"] = _iso(_now())
        _save("api_requests.json", api_requests)
        return _err("VALIDATION_ERROR", "offset must be an integer >= 0")

    items = _load("catalog_items.json")
    qn = q_name.lower() if isinstance(q_name, str) and q_name else None

    def match(r):
        if not isinstance(r, dict):
            return False
        if entity_type is not None and r.get("entity_type") != entity_type:
            return False
        if spotify_id is not None and r.get("spotify_id") != spotify_id:
            return False
        if cache_status is not None and r.get("cache_status") != cache_status:
            return False
        if owner_spotify_user_id is not None and r.get("owner_spotify_user_id") != owner_spotify_user_id:
            return False
        if qn is not None:
            nm = r.get("name")
            if not isinstance(nm, str) or qn not in nm.lower():
                return False
        return True

    filtered = [r for r in items if match(r)]

    # Sort: updated_at desc, then id
    def _parse_dt(s):
        if not isinstance(s, str):
            return datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        try:
            v = s[:-1] + "+00:00" if s.endswith("Z") else s
            dt = datetime.datetime.fromisoformat(v)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)

    filtered.sort(key=lambda r: (_parse_dt(r.get("updated_at")), r.get("id", "")), reverse=True)

    total = len(filtered)
    page = filtered[offset:offset + limit]
    has_more = offset + limit < total

    api_requests = _load("api_requests.json")
    _log_request(api_requests, "succeeded", None, {
        "entity_type": entity_type, "spotify_id": spotify_id, "cache_status": cache_status,
