        return _err("VALIDATION_ERROR", "id is required and must be a non-empty string")

    allowed_cache = {"fresh", "stale", "evicted"}
    if cache_status is not None:
        if not isinstance(cache_status, str) or cache_status not in allowed_cache:
            api_requests = _load("api_requests.json")
            _log_request(api_requests, "failed", "invalid cache_status", {"id": id, "cache_status": cache_status, "expires_at": expires_at, "raw_json": raw_json, "name": name, "description_text": description_text})
            api_requests[-1]["response_time_ms"] = int((time.time() - t0) * 1000)
            api_requests[-1]["updated_at"] = _iso(_now())
            _save("api_requests.json", api_requests)
            return _err("VALIDATION_ERROR", "Invalid cache_status", allowed=list(sorted(allowed_cache)))

    parsed_expires = None
    if expires_at is not None:
        dt, e = _parse_rfc3339(expires_at)
