            api_requests = _load("api_requests.json")
            _log_request(api_requests, "failed", "invalid expires_at", {"id": id, "cache_status": cache_status, "expires_at": expires_at, "raw_json": raw_json, "name": name, "description_text": description_text})
            api_requests[-1]["response_time_ms"] = int((time.time() - t0) * 1000)
            api_requests[-1]["updated_at"] = _iso(_now())
            _save("api_requests.json", api_requests)
            return _err("VALIDATION_ERROR", "Invalid expires_at: " + e)
        parsed_expires = dt

    if raw_json is not None and not isinstance(raw_json, dict):
        api_requests = _load("api_requests.json")
        _log_request(api_requests, "failed", "raw_json must be an object", {"id": id, "cache_status": cache_status, "expires_at": expires_at, "raw_json": raw_json, "name": name, "description_text": description_text})
