            api_requests[-1]["updated_at"] = _iso(_now())
            _save("api_requests.json", api_requests)
            return _err("VALIDATION_ERROR", f"{k} must be a string")

    items = _load("catalog_items.json")
    item = None
    for r in items:
        if isinstance(r, dict) and r.get("id") == id:
            item = r
            break

    api_requests = _load("api_requests.json")

    if item is None:
        _log_request(api_requests, "failed", "catalog item not found", {"id": id, "cache_status": cache_status, "expires_at": expires_at, "raw_json": raw_json, "name": name, "description_text": description_text})
