        return _err("NOT_FOUND", "catalog_items row not found", id=id)

    # lifecycle transitions
    transitions = {
        "fresh": {"stale", "evicted"},
        "stale": {"fresh", "evicted"},
        "evicted": {"fresh"},
    }
    if cache_status is not None and cache_status != item.get("cache_status"):
        cur = item.get("cache_status")
        if cur not in transitions or cache_status not in transitions[cur]:
