            return _err("INVALID_TRANSITION", f"Invalid cache_status transition {cur} -> {cache_status}")

    changed = False
    now = _now()

    if cache_status is not None and cache_status != item.get("cache_status"):
        item["cache_status"] = cache_status
        changed = True

    if parsed_expires is not None:
        # constraint: expires_at >= cached_at
        cached_raw = item.get("cached_at")
        cached_dt = None
        if isinstance(cached_raw, str):
            cached_dt, _ = _parse_rfc3339(cached_raw)
        if cached_dt is not None and parsed_expires < cached_dt:
            _log_request(api_requests, "failed", "expires_at must be >= cached_at", {"id": id, "cache_status": cache_status, "expires_at": expires_at, "raw_json": raw_json, "name": name, "description_text": description_text})
