            api_requests[-1]["updated_at"] = _iso(_now())
            _save("api_requests.json", api_requests)
            return _err("VALIDATION_ERROR", "name cannot be empty")
        item["name"] = name
        changed = True

    if description_text is not None:
        item["description_text"] = description_text
        changed = True

    # Re-validate a couple schema constraints if fields exist
    pop = item.get("popularity")
