            api_requests[-1]["updated_at"] = _iso(_now())
            _save("api_requests.json", api_requests)
            return _err("VALIDATION_ERROR", "popularity must be between 0 and 100")

    dur = item.get("duration_ms")
    if dur is not None:
        if not isinstance(dur, int) or dur < 0:
            _log_request(api_requests, "failed", "duration_ms invalid", {"id": id, "cache_status": cache_status, "expires_at": expires_at, "raw_json": raw_json, "name": name, "description_text": description_text})
