            _save("api_requests.json", api_requests)
            return _err("VALIDATION_ERROR", "duration_ms must be >= 0")

    if item.get("entity_type") == "playlist" and item.get("is_public") is None:
        _log_request(api_requests, "failed", "playlist requires is_public not null", {"id": id, "cache_status": cache_status, "expires_at": expires_at, "raw_json": raw_json, "name": name, "description_text": description_text})
        api_requests[-1]["response_time_ms"] = int((time.time() - t0) * 1000)
        api_requests[-1]["updated_at"] = _iso(_now())
        _save("api_requests.json", api_requests)
        return _err("VALIDATION_ERROR", "entity_type='playlist' implies is_public is not null")

    if not changed:
        _log_request(api_requests, "failed", "no fields to update", {"id": id, "cache_status": cache_status, "expires_at": expires_at, "raw_json": raw_json, "name": name, "description_text": description_text})
