        _save("api_requests.json", api_requests)
        return _err("VALIDATION_ERROR", "No updates supplied")

    item["updated_at"] = _iso(now)
    _save("catalog_items.json", items)

    _log_request(api_requests, "succeeded", None, {"id": id, "cache_status": cache_status, "expires_at": expires_at, "raw_json": raw_json, "name": name, "description_text": description_text})
