        _log_request(api_requests, "failed", "oauth_token_id must be a non-empty string", {
            "tool_name": tool_name, "oauth_token_id": oauth_token_id, "status": status,
            "result_cache_hit": result_cache_hit, "created_at_gte": created_at_gte, "created_at_lte": created_at_lte,
            "limit": limit, "offset": offset
        })
        api_requests[-1]["response_time_ms"] = int((time.time() - t0) * 1000)
        api_requests[-1]["updated_at"] = _iso(_now())
        _save("api_requests.json", api_requests)
        return _err("VALIDATION_ERROR", "oauth_token_id must be a non-empty string")

    allowed_status = {"succeeded", "failed"}
    if status is not None:
        if not isinstance(status, str) or status not in allowed_status:
            api_requests = _load("api_requests.json")
            _log_request(api_requests, "failed", "invalid status filter", {
                "tool_name": tool_name, "oauth_token_id": oauth_token_id, "status": status,
                "result_cache_hit": result_cache_hit, "created_at_gte": created_at_gte, "created_at_lte": created_at_lte,
                "limit": limit, "offset": offset
            })
            api_requests[-1]["response_time_ms"] = int((time.time() - t0) * 1000)
            api_requests[-1]["updated_at"] = _iso(_now())
            _save("api_requests.json", api_requests)
            return _err("VALIDATION_ERROR", "Invalid status", allowed=list(sorted(allowed_status)))

    if result_cache_hit is not None and not isinstance(result_cache_hit, bool):
        api_requests = _load("api_requests.json")
        _log_request(api_requests, "failed", "result_cache_hit must be boolean", {
            "tool_name": tool_name, "oauth_token_id": oauth_token_id, "status": status,
            "result_cache_hit": result_cache_hit, "created_at_gte": created_at_gte, "created_at_lte": created_at_lte,
            "limit": limit, "offset": offset
        })
        api_requests[-1]["response_time_ms"] = int((time.time() - t0) * 1000)
        api_requests[-1]["updated_at"] = _iso(_now())
        _save("api_requests.json", api_requests)
        return _err("VALIDATION_ERROR", "result_cache_hit must be a boolean")

    gte_dt = None
    lte_dt = None
    if created_at_gte is not None:
        gte_dt, e = _parse_rfc3339(created_at_gte)
        if e:
            api_requests = _load("api_requests.json")
            _log_request(api_requests, "failed", "invalid created_at_gte", {
                "tool_name": tool_name, "oauth_token_id": oauth_token_id, "status": status,
                "result_cache_hit": result_cache_hit, "created_at_gte": created_at_gte, "created_at_lte": created_at_lte,
                "limit": limit, "offset": offset
            })
            api_requests[-1]["response_time_ms"] = int((time.time() - t0) * 1000)
            api_requests[-1]["updated_at"] = _iso(_now())
            _save("api_requests.json", api_requests)
            return _err("VALIDATION_ERROR", "Invalid created_at_gte: " + e)
    if created_at_lte is not None:
        lte_dt, e = _parse_rfc3339(created_at_lte)
        if e:
            api_requests = _load("api_requests.json")
            _log_request(api_requests, "failed", "invalid created_at_lte", {
                "tool_name": tool_name, "oauth_token_id": oauth_token_id, "status": status,
                "result_cache_hit": result_cache_hit, "created_at_gte": created_at_gte, "created_at_lte": created_at_lte,
                "limit": limit, "offset": offset
            })
            api_requests[-1]["response_time_ms"] = int((time.time() - t0) * 1000)
            api_requests[-1]["updated_at"] = _iso(_now())
            _save("api_requests.json", api_requests)
            return _err("VALIDATION_ERROR", "Invalid created_at_lte: " + e)
    if gte_dt is not None and lte_dt is not None and gte_dt > lte_dt:
        api_requests = _load("api_requests.json")
        _log_request(api_requests, "failed", "created_at_gte must be <= created_at_lte", {
            "tool_name": tool_name, "oauth_token_id": oauth_token_id, "status": status,
            "result_cache_hit": result_cache_hit, "created_at_gte": created_at_gte, "created_at_lte": created_at_lte,
            "limit": limit, "offset": offset
        })
        api_requests[-1]["response_time_ms"] = int((time.time() - t0) * 1000)
        api_requests[-1]["updated_at"] = _iso(_now())
        _save("api_requests.json", api_requests)
        return _err("VALIDATION_ERROR", "created_at_gte must be <= created_at_lte")

    if limit is None:
        limit = 50
    if offset is None:
        offset = 0
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        api_requests = _load("api_requests.json")
        _log_request(api_requests, "failed", "invalid limit", {
            "tool_name": tool_name, "oauth_token_id": oauth_token_id, "status": status,
            "result_cache_hit": result_cache_hit, "created_at_gte": created_at_gte, "created_at_lte": created_at_lte,
            "limit": limit, "offset": offset
        })
        api_requests[-1]["response_time_ms"] = int((time.time() - t0) * 1000)
        api_requests[-1]["updated_at"] = _iso(_now())
        _save("api_requests.json", api_requests)
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200")
    if not isinstance(offset, int) or offset < 0:
        api_requests = _load("api_requests.json")
        _log_request(api_requests, "failed", "invalid offset", {
            "tool_name": tool_name, "oauth_token_id": oauth_token_id, "status": status,
            "result_cache_hit": result_cache_hit, "created_at_gte": created_at_gte, "created_at_lte": created_at_lte,
            "limit": limit, "offset": offset
        })
        api_requests[-1]["response_time_ms"] = int((time.time() - t0) * 1000)
        api_requests[-1]["updated_at"] = _iso(_now())
        _save("api_requests.json", api_requests)
        return _err("VALIDATION_ERROR", "offset must be an integer >= 0")

    rows = _load("api_requests.json")

    def _row_dt(r):
        s = r.get("created_at")
        if not isinstance(s, str):
            return None
        dt, _ = _parse_rfc3339(s)
        return dt

    def match(r):
        if not isinstance(r, dict):
            return False
        if tool_name is not None and r.get("tool_name") != tool_name:
            return False
        if oauth_token_id is not None and r.get("oauth_token_id") != oauth_token_id:
            return False
        if status is not None and r.get("status") != status:
            return False
        if result_cache_hit is not None and r.get("result_cache_hit") != result_cache_hit:
            return False
        if gte_dt is not None or lte_dt is not None:
            dt = _row_dt(r)
            if dt is None:
                return False
            if gte_dt is not None and dt < gte_dt:
                return False
            if lte_dt is not None and dt > lte_dt:
                return False
        return True

    filtered = [r for r in rows if match(r)]

    # Sort by created_at desc then id
    def _sort_key(r):
        dt = _row_dt(r)
        if dt is None:
            dt = datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        return (dt, r.get("id", ""))

    filtered.sort(key=_sort_key, reverse=True)

    total = len(filtered)
    page = filtered[offset:offset + limit]
    has_more = offset + limit < total

    # Log this read invocation too
    api_requests2 = rows  # same list object
    _log_request(api_requests2, "succeeded", None, {
        "tool_name": tool_name, "oauth_token_id": oauth_token_id, "status": status,
        "result_cache_hit": result_cache_hit, "created_at_gte": created_at_gte, "created_at_lte": created_at_lte,
        "limit": limit, "offset": offset
    })
    api_requests2[-1]["response_time_ms"] = int((time.time() - t0) * 1000)
    api_requests2[-1]["updated_at"] = _iso(_now())
    _save("api_requests.json", api_requests2)

    return {
        "api_requests": page,
        "pagination": {
            "total": total,
            "limit": limit,
            "offset": offset,
            "has_more": has_more,
            "next_offset": (offset + limit) if has_more else None,
        },
    }
